-- =============================================================================
-- Studuel — Migration 231 : ESPAGNOL Tle — LE PROGRAMME OFFICIEL
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main.
--    Source : scripts/contenu/*.mjs
--    Regénérer : node scripts/seed-contenu.mjs --num 231 --modules espagnol-tle
--
-- CONSTAT MESURÉ (sonde en lecture seule sur la base, 05/08/2026) :
-- l'espagnol du lycée n'avait que 3 chapitres, identiques en 2de, 1re et Tle,
-- taillés dans un découpage maison (« Les temps du passé », « Ser, estar et les
-- tournures essentielles », « Le monde hispanique aujourd'hui »). Un élève de
-- Terminale qui révisait la négation, l'enclise des pronoms, cuyo, l'apocope, le
-- subjonctif ou la concordance ne trouvait RIEN — alors que ce sont exactement
-- les points sur lesquels une copie se perd. Cette migration installe les 34
-- fiches du programme officiel, dans l'ordre de ses 4 chapitres (la phrase, le
-- groupe nominal, le groupe verbal, les temps), et retire les 2 fiches de
-- synthèse que ce découpage recouvre entièrement.
-- PÉRIMÈTRE : la TERMINALE SEULE — c'est le programme de l'année du bac. La 2de
-- et la 1re conservent telles quelles les 3 fiches de la 220 : le ménage est
-- borné au niveau Tle, sans quoi il les viderait aux deux tiers sans rien
-- mettre à la place. La fiche « Le monde hispanique aujourd'hui » est CONSERVÉE
-- côté Terminale aussi — elle porte les axes culturels du bac, qu'aucune fiche de
-- grammaire ne remplace — mais renvoyée en fin de liste.
--
-- Cette migration apporte : 34 chapitres, 34 leçons,
-- 34 quiz et 272 questions, sur 1 matière.
--
-- CHOIX ASSUMÉS :
--  · tous les quiz sont `is_free = true`. Aucun compte ne peut aujourd’hui
--    passer `tier1` (aucun paiement n’existe), donc un quiz payant serait un
--    quiz INVISIBLE pour 100 % des élèves — le contraire du but ;
--  · chaque cours porte des sections `##`, ce qui rend sa carte mentale
--    dérivable (cf. lib/mind-map-auto) : aucune tuile ne promet dans le vide.
--
-- Idempotent : les UUID sont dérivés du contenu (SHA-1), donc stables ; les
-- INSERT sont tous gardés par ON CONFLICT DO NOTHING. Rejouable sans risque.
--
-- PRÉREQUIS : 002, 008, 191, 193 exécutées (les matières doivent exister).
-- À exécuter dans : Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

-- 0. Ménage ----------------------------------------------------------------
-- [espagnol] La file « À revoir » d'abord : review_items.item_id n'a PAS de clé
-- [espagnol] étrangère (il pointe soit une question, soit une carte). Rien ne casse si on
-- [espagnol] l'oublie — le lecteur écarte déjà un contenu disparu — mais le compteur
-- [espagnol] « X à revoir » continuerait de compter des questions qui n'existent plus.
DELETE FROM public.review_items ri
 USING public.quiz_questions qq, public.quizzes qz, public.lessons l,
       public.chapters c, public.subjects s
 WHERE ri.item_kind = 'question'
   AND ri.item_id = qq.id
   AND qq.quiz_id = qz.id
   AND qz.lesson_id = l.id
   AND l.chapter_id = c.id
   AND c.subject_id = s.id
   AND s.slug = 'espagnol'
   AND c.level = 'Tle'
   AND l.title IN ('Pretérito, imperfecto, perfecto',
                   'Deux verbes « être », et tout change');

-- [espagnol] Les quiz ensuite : quizzes.lesson_id est ON DELETE SET NULL, donc
-- [espagnol] supprimer le chapitre laisserait derrière lui des quiz orphelins, rattachés à
-- [espagnol] aucune leçon mais toujours servis par le moteur de révision.
DELETE FROM public.quizzes q
 USING public.lessons l, public.chapters c, public.subjects s
 WHERE q.lesson_id = l.id
   AND l.chapter_id = c.id
   AND c.subject_id = s.id
   AND s.slug = 'espagnol'
   AND c.level = 'Tle'
   AND l.title IN ('Pretérito, imperfecto, perfecto',
                   'Deux verbes « être », et tout change');

-- [espagnol] Puis les chapitres : leçons, fiches de révision, supports, progression
-- [espagnol] et chapitres cochés partent en cascade (toutes les clés étrangères vers
-- [espagnol] chapters et lessons sont ON DELETE CASCADE).
DELETE FROM public.chapters c
 USING public.subjects s
 WHERE c.subject_id = s.id
   AND s.slug = 'espagnol'
   AND c.level = 'Tle'
   AND EXISTS (
     SELECT 1 FROM public.lessons l
      WHERE l.chapter_id = c.id
        AND l.title IN ('Pretérito, imperfecto, perfecto',
                        'Deux verbes « être », et tout change')
   );

-- [espagnol] Enfin la fiche culturelle SURVIVANTE passe en fin de liste, en
-- [espagnol] Terminale seulement. Elle reste utile (les axes du bac ne sont pas de la
-- [espagnol] grammaire), mais elle occupe la position 3, en plein milieu des 34 fiches
-- [espagnol] neuves. Un INSERT ne peut pas renuméroter une ligne déjà en base : c'est un
-- [espagnol] UPDATE, ici, ou rien. Idempotent (rejouer réécrit la même valeur). En 2de et en
-- [espagnol] 1re, elle ne bouge pas — rien ne vient s'intercaler devant elle.
UPDATE public.chapters c
   SET position = 90
  FROM public.subjects s
 WHERE c.subject_id = s.id
   AND s.slug = 'espagnol'
   AND c.level = 'Tle'
   AND c.title = 'Le monde hispanique aujourd’hui';

