ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('e4e0d50d-7c9a-5741-b580-2bd04de915cb'::uuid, '97ade61e-2561-59dd-b8b9-50d3dce86858'::uuid, 'Comment s’écrit une question en espagnol ?', 'mcq', '["Avec un ¿ à l’ouverture et un ? à la fermeture","Avec un seul ? final","Avec un ¿ seulement","Avec « est-ce que » puis un ?"]'::jsonb, 0, 'Le ¿ se place au début de la partie interrogée, pas forcément de la phrase.', 1),
    ('f2765840-6faa-57b4-9a67-0a9f9affa33f'::uuid, '97ade61e-2561-59dd-b8b9-50d3dce86858'::uuid, 'Les mots interrogatifs espagnols portent tous un accent écrit.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est lui qui distingue *dónde* (interrogatif) de *donde* (relatif).', 2),
    ('15f29b4f-66a9-59c4-96dc-11c471dcf42d'::uuid, '97ade61e-2561-59dd-b8b9-50d3dce86858'::uuid, 'Que demande « cuál » plutôt que « qué » ?', 'mcq', '["Un choix dans un ensemble","Une définition","Une cause","Une quantité"]'::jsonb, 0, '*¿Cuál prefieres?* suppose plusieurs possibilités déjà connues.', 3),
    ('ac6940e0-ee4c-58ce-af03-fdecdec04693'::uuid, '97ade61e-2561-59dd-b8b9-50d3dce86858'::uuid, 'Comment traduire « Pourquoi pleures-tu ? » ?', 'mcq', '["¿Por qué lloras?","¿Porque lloras?","¿Porqué lloras?","¿Por que lloras?"]'::jsonb, 0, 'En deux mots et avec l’accent : c’est la question, pas la réponse.', 4),
    ('d0e09732-da86-5a8d-89df-5069f71ae90b'::uuid, '97ade61e-2561-59dd-b8b9-50d3dce86858'::uuid, '« El porqué » est un nom masculin qui signifie « la raison ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*No entiendo el porqué de su decisión.*', 5),
    ('b353a70d-fd79-5f0c-a672-e87b767a91e6'::uuid, '97ade61e-2561-59dd-b8b9-50d3dce86858'::uuid, 'Dans « No sé dónde está », l’accent sur « dónde »…', 'mcq', '["Se maintient malgré l’absence de point d’interrogation","Disparaît","Devient facultatif","Se déplace"]'::jsonb, 0, 'C’est une interrogation indirecte : l’accent reste, les signes ¿ ? partent.', 6),
    ('ed9cade2-29fb-5953-9f37-1452c9456ea7'::uuid, '97ade61e-2561-59dd-b8b9-50d3dce86858'::uuid, 'L’espagnol exige l’inversion du sujet dans toute question.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*¿Tú hablas español?* est parfaitement correct : l’intonation suffit.', 7),
    ('aa47da70-f1af-504f-8790-84402784cd68'::uuid, '97ade61e-2561-59dd-b8b9-50d3dce86858'::uuid, 'Devant un nom, l’espagnol préfère…', 'mcq', '["Qué (¿Qué día es hoy?)","Cuál (¿Cuál día es hoy?)","Quién","Cuánto"]'::jsonb, 0, '*¿Cuál día?* est un calque du français à éviter.', 8),
    ('739daafb-52b7-5adf-bfc1-110e79efb6f1'::uuid, '0c020bb6-1142-5db8-8dbb-959731f21661'::uuid, 'Où se place « no » dans la phrase ?', 'mcq', '["Juste devant le verbe","À la fin de la phrase","Après le verbe","Devant le sujet"]'::jsonb, 0, 'Seuls les pronoms compléments peuvent s’intercaler : *No te lo digo.*', 1),
    ('a1c95c29-788c-541e-812c-0424207c1a33'::uuid, '0c020bb6-1142-5db8-8dbb-959731f21661'::uuid, 'Comment traduire « je ne vois rien » ?', 'mcq', '["No veo nada","Veo nada","No veo","Nada veo no"]'::jsonb, 0, 'La double négation est obligatoire quand le mot négatif suit le verbe.', 2),
    ('fc404d5a-0680-54d0-89a9-a248d801a3be'::uuid, '0c020bb6-1142-5db8-8dbb-959731f21661'::uuid, '« Nadie viene » est incorrect : il manque le « no ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Quand le mot négatif précède le verbe, le *no* disparaît.', 3),
    ('fbfa7ba6-74e4-5907-9ba3-52dfe54e8078'::uuid, '0c020bb6-1142-5db8-8dbb-959731f21661'::uuid, 'Que signifie « tampoco » ?', 'mcq', '["Non plus","Encore","Déjà","Jamais"]'::jsonb, 0, '*A mí tampoco me gusta* : à moi non plus.', 4),
    ('fbebb52f-5572-5ccd-9614-bfd66dbd9e73'::uuid, '0c020bb6-1142-5db8-8dbb-959731f21661'::uuid, '*___ fumo* : je ne fume plus.', 'mcq', '["Ya no","Todavía no","Nunca","Ni"]'::jsonb, 0, '*Ya no* marque l’arrêt ; *todavía no* signifie « pas encore ».', 5),
    ('b434ab63-9ff8-5c5b-a8d8-5c43ff54eafc'::uuid, '0c020bb6-1142-5db8-8dbb-959731f21661'::uuid, '*No es francés ___ español.*', 'mcq', '["sino","pero","porque","aunque"]'::jsonb, 0, 'Après une négation, on rectifie avec *sino*. *Pero* oppose sans rectifier.', 6),
    ('5a1cfa02-2019-5478-806f-0e3b5c523b72'::uuid, '0c020bb6-1142-5db8-8dbb-959731f21661'::uuid, '« Ninguno » s’apocope en « ningún » devant un masculin singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ningún libro*, mais *ninguna casa* et *ninguno de ellos*.', 7),
    ('fa09ed18-fc73-5835-a55c-0efaf018e764'::uuid, '0c020bb6-1142-5db8-8dbb-959731f21661'::uuid, '*No canta ___ grita.*', 'mcq', '["sino que","sino","sino de","pero que"]'::jsonb, 0, 'Devant un VERBE CONJUGUÉ, *sino* devient *sino que*.', 8),
    ('f2981f2b-a439-5e23-984f-b89a72c7783b'::uuid, '39141912-d3c2-56a9-a581-a4c279314243'::uuid, 'Quelle relative s’écrit entre virgules ?', 'mcq', '["L’explicative","La déterminative","Les deux","Aucune"]'::jsonb, 0, 'L’explicative ajoute une information supprimable.', 1),
    ('08564d18-b9b5-5ebc-808e-0a0a7c07569b'::uuid, '39141912-d3c2-56a9-a581-a4c279314243'::uuid, '« Busco una secretaria que hable inglés » emploie le subjonctif parce que…', 'mcq', '["L’antécédent est indéfini : elle reste à trouver","L’antécédent est connu","La relative est explicative","Le verbe est irrégulier"]'::jsonb, 0, 'Avec un antécédent réel, l’indicatif : *que habla inglés*.', 2),
    ('088a9c2b-d3f2-5c9e-af55-602d84f1c3c2'::uuid, '39141912-d3c2-56a9-a581-a4c279314243'::uuid, 'La virgule d’une relative ne change pas le sens de la phrase.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Los alumnos que estudian* ne désigne pas les mêmes élèves que *los alumnos, que estudian*.', 3),
    ('f0023abc-0e9d-568c-a37b-c228a180eacb'::uuid, '39141912-d3c2-56a9-a581-a4c279314243'::uuid, 'Comment traduire « la maison dans laquelle je vis » ?', 'mcq', '["La casa en la que vivo","La casa que vivo en","La casa vivo en que","La casa en vivo que"]'::jsonb, 0, 'La préposition précède toujours le relatif en espagnol.', 4),
    ('2d0d3f96-65c0-50c8-87f2-4679e516b9c3'::uuid, '39141912-d3c2-56a9-a581-a4c279314243'::uuid, '*No conozco a nadie que ___ ruso.*', 'mcq', '["hable","habla","hablar","hablará"]'::jsonb, 0, 'La négation rend l’antécédent inexistant, donc indéfini : subjonctif.', 5),
    ('a192ee46-dc6c-5dfb-bfa8-06ed45b78290'::uuid, '39141912-d3c2-56a9-a581-a4c279314243'::uuid, '*Llegó tarde, ___ me molestó.*', 'mcq', '["lo que","el que","quien","cuyo"]'::jsonb, 0, 'Le neutre *lo que* reprend une idée entière, pas un nom.', 6),
    ('c6cca7e0-6dc8-5129-8548-03313c3ae384'::uuid, '39141912-d3c2-56a9-a581-a4c279314243'::uuid, 'Dans une relative déterminative, on emploie normalement « que ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Quien* est réservé aux explicatives et aux emplois avec préposition.', 7),
    ('76492fa0-44a4-54a9-99c9-cb4e29085723'::uuid, '39141912-d3c2-56a9-a581-a4c279314243'::uuid, '« El que quiera, que venga » se traduit par…', 'mcq', '["Que celui qui veut vienne","Ce qu’il veut, qu’il vienne","Celui qu’il veut vient","Il veut qu’il vienne"]'::jsonb, 0, 'Relatif sans antécédent exprimé, suivi du subjonctif.', 8),
    ('591e663e-30ab-54d4-840c-8b1a96a2222d'::uuid, '747d07c4-9b9b-54e0-93f8-4d35d53ec646'::uuid, '*Quiero que ___ mañana.*', 'mcq', '["vengas","vienes","venir","vendrás"]'::jsonb, 0, 'La volonté commande le subjonctif dès que le sujet change.', 1),
    ('0d9c3991-fa41-506b-a126-3fb10be33c8d'::uuid, '747d07c4-9b9b-54e0-93f8-4d35d53ec646'::uuid, '« Creo que viene » et « No creo que venga » emploient le même mode.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Nier la certitude fait passer l’indicatif au subjonctif.', 2),
    ('60323dd8-a34f-54ad-9423-8462c9c99ec8'::uuid, '747d07c4-9b9b-54e0-93f8-4d35d53ec646'::uuid, 'Comment dit-on « je veux venir » (même sujet) ?', 'mcq', '["Quiero venir","Quiero que venga","Quiero que vengo","Quiero de venir"]'::jsonb, 0, 'Même sujet : infinitif, sans *que*.', 3),
    ('f9450b34-0710-55f9-b19f-d8ff15e78062'::uuid, '747d07c4-9b9b-54e0-93f8-4d35d53ec646'::uuid, '*Es necesario que ___ más.*', 'mcq', '["estudies","estudias","estudiar","estudiarás"]'::jsonb, 0, 'Le jugement impersonnel commande le subjonctif.', 4),
    ('2ad1882b-e856-5beb-84fd-bfc2085d3b54'::uuid, '747d07c4-9b9b-54e0-93f8-4d35d53ec646'::uuid, '« Ojalá » est toujours suivi du subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ojalá llueva* : c’est l’expression du souhait par excellence.', 5),
    ('6d3710c9-dd39-5c39-8715-8935e707ef2f'::uuid, '747d07c4-9b9b-54e0-93f8-4d35d53ec646'::uuid, 'Quand le verbe principal est au passé, le subjonctif présent devient…', 'mcq', '["L’imparfait du subjonctif","Le passé simple","Le conditionnel","Le futur"]'::jsonb, 0, '*Quería que vinieras* — les formes en -ra et en -se sont équivalentes.', 6),
    ('637fe583-cda8-59a8-a3d1-80192e2c912b'::uuid, '747d07c4-9b9b-54e0-93f8-4d35d53ec646'::uuid, 'Après « Dudo que… », on emploie l’indicatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le doute appelle le subjonctif : *Dudo que sea verdad.*', 7),
    ('18f4c01d-86f8-59c8-ab96-966286a3320f'::uuid, '747d07c4-9b9b-54e0-93f8-4d35d53ec646'::uuid, 'Le « que » de la complétive peut être supprimé en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il se maintient toujours : *Espero que me llames.*', 8),
    ('1243c0a5-5645-5735-8ff3-0bad4f84d0bc'::uuid, 'd814d55f-d016-537f-84f7-a6a459f07a1d'::uuid, 'Quel est le genre de « la sangre » ?', 'mcq', '["Féminin","Masculin","Neutre","Les deux"]'::jsonb, 0, 'Piège classique : le français dit « le sang ».', 1),
    ('9afa34b3-a435-557f-b5a8-78ce6f2a0b1a'::uuid, 'd814d55f-d016-537f-84f7-a6a459f07a1d'::uuid, 'Les noms en « -ción » et « -dad » sont féminins.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*La canción*, *la ciudad*, *la libertad*.', 2),
    ('49660d21-1bec-5058-811f-861a12dcfe78'::uuid, 'd814d55f-d016-537f-84f7-a6a459f07a1d'::uuid, 'Quel est le genre de « el problema » ?', 'mcq', '["Masculin, malgré le -a final","Féminin","Variable","Neutre"]'::jsonb, 0, 'Comme *el tema*, *el idioma*, *el sistema* : origine grecque.', 3),
    ('a7d0dfb7-e29c-567d-92b8-7a7c7299cdcf'::uuid, 'd814d55f-d016-537f-84f7-a6a459f07a1d'::uuid, 'Quel est le pluriel de « lápiz » ?', 'mcq', '["Lápices","Lápizs","Lápizes","Lápiz"]'::jsonb, 0, 'Le -z devient -c devant -es.', 4),
    ('86cf5053-6711-56bc-84a1-819109682500'::uuid, 'd814d55f-d016-537f-84f7-a6a459f07a1d'::uuid, '« El lunes » au pluriel devient « los lunes ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les mots en -s non accentués sur la dernière syllabe sont invariables.', 5),
    ('1627b02d-c4b3-5e64-a108-f9b990bb7ae7'::uuid, 'd814d55f-d016-537f-84f7-a6a459f07a1d'::uuid, 'Quel est le pluriel de « el examen » ?', 'mcq', '["Los exámenes","Los examenes","Los exámens","Los examen"]'::jsonb, 0, 'L’accent écrit apparaît pour conserver la même syllabe tonique.', 6),
    ('aceadd0b-2c85-50f4-b5b0-49fed4cee63a'::uuid, 'd814d55f-d016-537f-84f7-a6a459f07a1d'::uuid, '« El color » est masculin en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Alors que le français hésite : la couleur est féminine.', 7),
    ('7eb8d5cf-a857-58b9-9f7c-68070891d1f0'::uuid, 'd814d55f-d016-537f-84f7-a6a459f07a1d'::uuid, 'Comment se forme le pluriel après une consonne ?', 'mcq', '["On ajoute -es","On ajoute -s","On ne change rien","On double la consonne"]'::jsonb, 0, '*Papel → papeles*, *ciudad → ciudades*.', 8),
    ('d994844f-b4c1-5ef2-a3fa-03e68bfabdf5'::uuid, '9b05cfcf-3a2f-5644-8100-f82f8538c0b3'::uuid, 'Quelles sont les deux contractions de l’espagnol ?', 'mcq', '["Al et del","Al, del et col","Del seulement","Al, del, pel"]'::jsonb, 0, '*a + el = al*, *de + el = del*.', 1),
    ('c7c6ece7-b6ff-5308-b37e-1596f52be6dd'::uuid, '9b05cfcf-3a2f-5644-8100-f82f8538c0b3'::uuid, 'Pourquoi dit-on « el agua » ?', 'mcq', '["Le nom féminin commence par un a- tonique","Le nom est masculin","C’est une exception isolée","L’article est neutre"]'::jsonb, 0, 'Le mot reste féminin : *el agua fría*, *las aguas*.', 2),
    ('a350d3a2-84fc-59eb-8d52-c7d27d784d8b'::uuid, '9b05cfcf-3a2f-5644-8100-f82f8538c0b3'::uuid, '« El agua » devient « los aguas » au pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le pluriel reprend l’article féminin : *las aguas*.', 3),
    ('7e46fe05-b657-51ac-bff6-77b8bcb6b57f'::uuid, '9b05cfcf-3a2f-5644-8100-f82f8538c0b3'::uuid, 'Que précède l’article neutre « lo » ?', 'mcq', '["Un adjectif, un adverbe ou un relatif","Un nom masculin","Un nom féminin","Un verbe"]'::jsonb, 0, '*Lo importante*, *lo mejor*, *lo que dices*.', 4),
    ('0c7b506b-d52d-5f3d-886f-c8d146541202'::uuid, '9b05cfcf-3a2f-5644-8100-f82f8538c0b3'::uuid, 'Comment dit-on « je suis professeur » ?', 'mcq', '["Soy profesor","Soy un profesor","Estoy profesor","Soy el profesor"]'::jsonb, 0, 'Pas d’article devant une profession attribut, sauf si elle est qualifiée.', 5),
    ('4a3e8364-ded7-5db4-802d-c03e0384a678'::uuid, '9b05cfcf-3a2f-5644-8100-f82f8538c0b3'::uuid, '« Unos amigos » signifie « quelques amis ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le pluriel de l’indéfini exprime l’approximation.', 6),
    ('a58388cb-2033-5046-82ca-975306e8d3b3'::uuid, '9b05cfcf-3a2f-5644-8100-f82f8538c0b3'::uuid, 'Comment traduire « un autre jour » ?', 'mcq', '["Otro día","Un otro día","El otro día","Uno otro día"]'::jsonb, 0, '*Otro* ne prend jamais l’article indéfini.', 7),
    ('f535aa9e-0fa8-582c-b3dc-3cd9c7f3a064'::uuid, '9b05cfcf-3a2f-5644-8100-f82f8538c0b3'::uuid, '« La avenida » ne prend pas « el » parce que…', 'mcq', '["L’accent tonique ne tombe pas sur le a initial","Le mot est masculin","Le mot est pluriel","Le mot est étranger"]'::jsonb, 0, 'La règle ne vaut que pour un a- ou ha- TONIQUE.', 8),
    ('cb58c1cf-0c68-5071-b196-6e6476efbd1f'::uuid, '24f93a67-6b4c-5bba-a9e2-0e9554dfd932'::uuid, 'Combien l’espagnol a-t-il de séries de démonstratifs ?', 'mcq', '["Trois : este, ese, aquel","Deux : este et ese","Une seule","Quatre"]'::jsonb, 0, 'Elles correspondent à *aquí*, *ahí*, *allí*.', 1),
    ('dca12358-1698-51c9-a0cc-c9f0dd6430ca'::uuid, '24f93a67-6b4c-5bba-a9e2-0e9554dfd932'::uuid, 'Quel démonstratif désigne ce qui est près de l’interlocuteur ?', 'mcq', '["Ese","Este","Aquel","Esto"]'::jsonb, 0, '*Ese libro que tienes en la mano.*', 2),
    ('1c9bbf92-be8b-5d79-a4f2-e1635f575b47'::uuid, '24f93a67-6b4c-5bba-a9e2-0e9554dfd932'::uuid, 'Les démonstratifs neutres « esto, eso, aquello » sont invariables.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et ils ne sont jamais suivis d’un nom.', 3),
    ('56d32140-d109-5f28-a494-9f7163f4fc7a'::uuid, '24f93a67-6b4c-5bba-a9e2-0e9554dfd932'::uuid, 'Comment reprendre une phrase entière ?', 'mcq', '["Par un neutre : eso","Par ese","Par esta","Par aquellos"]'::jsonb, 0, '*No vino, y eso me molestó.*', 4),
    ('b14eee22-2adf-5398-926e-3c8b178f5454'::uuid, '24f93a67-6b4c-5bba-a9e2-0e9554dfd932'::uuid, 'Depuis 2010, le pronom démonstratif porte un accent écrit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La RAE l’a supprimé : on écrit *este* pronom comme *este* adjectif.', 5),
    ('04627102-23c1-5c9e-875f-f40a5a27d2d1'::uuid, '24f93a67-6b4c-5bba-a9e2-0e9554dfd932'::uuid, '« Aquellos tiempos » évoque…', 'mcq', '["Une époque lointaine","L’instant présent","Le futur proche","La semaine dernière"]'::jsonb, 0, '*Aquel* marque la plus grande distance, y compris temporelle.', 6),
    ('33fd181f-84cb-5922-a85d-1e67d7159bd9'::uuid, '24f93a67-6b4c-5bba-a9e2-0e9554dfd932'::uuid, '*¿Qué es ___?* — « qu’est-ce que c’est ? »', 'mcq', '["esto","este","ésta","ese"]'::jsonb, 0, 'On désigne une chose non identifiée : c’est le NEUTRE *esto*.', 7),
    ('1598e694-400a-5fbc-83c4-aafd003255a3'::uuid, '24f93a67-6b4c-5bba-a9e2-0e9554dfd932'::uuid, '« Esta » et « estas » sont les formes féminines de « este ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Masculin : *este / estos* ; féminin : *esta / estas*.', 8),
    ('3750ca14-84c3-5a2a-a641-2e91f9ae6733'::uuid, 'ce7ab2f1-f94e-5b41-8d2e-79e8769ada0b'::uuid, 'Où se place l’adjectif espagnol par défaut ?', 'mcq', '["Après le nom","Avant le nom","En fin de phrase","Avant le verbe"]'::jsonb, 0, 'C’est la position qui classe objectivement : *un coche rojo*.', 1),
    ('ca7cc504-e733-5e44-a7fe-48ef9d762d90'::uuid, 'ce7ab2f1-f94e-5b41-8d2e-79e8769ada0b'::uuid, '« Un gran hombre » et « un hombre grande » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier est un grand homme, le second un homme de grande taille.', 2),
    ('83aac6c5-b221-54b0-ba4f-ec726d6201cf'::uuid, 'ce7ab2f1-f94e-5b41-8d2e-79e8769ada0b'::uuid, 'Quel adjectif a quatre formes ?', 'mcq', '["Alto (alto, alta, altos, altas)","Inteligente","Fácil","Verde"]'::jsonb, 0, 'Les adjectifs en -e ou en consonne sont invariables en genre.', 3),
    ('36781a8e-a2a4-5925-a249-0195ca5c4b34'::uuid, 'ce7ab2f1-f94e-5b41-8d2e-79e8769ada0b'::uuid, '« Un chico y una chica simpáticos » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec des noms de genres différents, l’adjectif se met au masculin pluriel.', 4),
    ('9fca7265-bdfa-5b41-ae06-e37bab734918'::uuid, 'ce7ab2f1-f94e-5b41-8d2e-79e8769ada0b'::uuid, 'Que signifie « un pobre hombre » ?', 'mcq', '["Un homme à plaindre","Un homme sans argent","Un homme humble","Un homme malade"]'::jsonb, 0, 'Placé après, *un hombre pobre* désigne la pauvreté matérielle.', 5),
    ('c274c9ba-e60b-5ba2-a324-3de2b4d91eac'::uuid, 'ce7ab2f1-f94e-5b41-8d2e-79e8769ada0b'::uuid, 'Les adjectifs de nationalité forment un féminin.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Español/española*, *inglés/inglesa*, même s’ils finissent par une consonne.', 6),
    ('dc25d3fb-b8f5-57db-92e2-ee1bd45fecc0'::uuid, 'ce7ab2f1-f94e-5b41-8d2e-79e8769ada0b'::uuid, '« Un viejo amigo » signifie…', 'mcq', '["Un ami de longue date","Un ami âgé","Un ancien ami fâché","Un ami d’enfance uniquement"]'::jsonb, 0, 'La place avant le nom porte l’appréciation, pas l’âge.', 7),
    ('fad1152b-9d93-57d4-abbd-cd59f0ff7670'::uuid, 'ce7ab2f1-f94e-5b41-8d2e-79e8769ada0b'::uuid, 'Un adjectif placé avant le nom exprime souvent une appréciation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*La blanca nieve*, *un buen amigo* : le regard de celui qui parle.', 8),
    ('744b6d36-20f5-59fa-9f16-bc62717ddb2b'::uuid, 'd538b68f-ca52-5f12-9a7b-5ef4137ab2a7'::uuid, 'Pourquoi l’espagnol omet-il souvent le pronom sujet ?', 'mcq', '["La terminaison du verbe identifie déjà la personne","C’est un usage familier","Pour aller plus vite","Le pronom n’existe pas"]'::jsonb, 0, 'On l’exprime pour insister, opposer ou lever une ambiguïté.', 1),
    ('20758f57-984c-5fcb-bc59-3f28117ebaeb'::uuid, 'd538b68f-ca52-5f12-9a7b-5ef4137ab2a7'::uuid, '« Usted » se conjugue à la deuxième personne.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'À la troisième : *¿Usted habla español?* — il vient de *vuestra merced*.', 2),
    ('a65c0a83-430d-5224-abe4-0d53f3d2a0c9'::uuid, 'd538b68f-ca52-5f12-9a7b-5ef4137ab2a7'::uuid, 'Quel pronom remplace « vosotros » en Amérique latine ?', 'mcq', '["Ustedes","Vos","Tú","Nosotros"]'::jsonb, 0, '*Vosotros* n’y est pas employé, même entre amis.', 3),
    ('317520e9-88e1-5f16-951e-6816f1e98f1e'::uuid, 'd538b68f-ca52-5f12-9a7b-5ef4137ab2a7'::uuid, 'Le « voseo » consiste à employer…', 'mcq', '["Vos à la place de tú","Usted à la place de tú","Vosotros à la place d’ustedes","Nos à la place de nosotros"]'::jsonb, 0, '*Vos tenés*, *vos sos* : norme d’Argentine, d’Uruguay, du Paraguay.', 4),
    ('798902f7-63fe-55de-81ec-ebe0f751ec66'::uuid, 'd538b68f-ca52-5f12-9a7b-5ef4137ab2a7'::uuid, '*Este regalo es para ___.*', 'mcq', '["mí","yo","me","mi"]'::jsonb, 0, 'Après préposition, le pronom tonique *mí* — avec accent, sinon c’est le possessif.', 5),
    ('7c3aa672-2dc0-5d74-92e7-abf3a9b356cb'::uuid, 'd538b68f-ca52-5f12-9a7b-5ef4137ab2a7'::uuid, '« Conmigo » et « contigo » sont des formes soudées irrégulières.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On ne dit jamais « con mí » ni « con ti ».', 6),
    ('f261e622-d0d7-518a-9b46-8f976d6bc0a7'::uuid, 'd538b68f-ca52-5f12-9a7b-5ef4137ab2a7'::uuid, '*Según ___, la película es buena.*', 'mcq', '["yo","mí","me","conmigo"]'::jsonb, 0, '*Entre* et *según* sont les deux exceptions : elles gardent le pronom SUJET.', 7),
    ('fd764d42-df8c-5512-bd84-6190a1e53585'::uuid, 'd538b68f-ca52-5f12-9a7b-5ef4137ab2a7'::uuid, '« Yo no lo he dicho » exprime une insistance.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sans le *yo*, la phrase serait neutre : le pronom souligne le contraste.', 8),
    ('d5cf8dba-cefa-58de-811e-bbc57c0e95f1'::uuid, '5fd16d27-a484-5313-9a94-cc1eff3f673b'::uuid, 'Dans quel ordre se placent les pronoms compléments ?', 'mcq', '["COI puis COD","COD puis COI","Selon la longueur du mot","Indifféremment"]'::jsonb, 0, '*Me lo da*, *te la doy* : le COI passe toujours devant.', 1),
    ('b53ca030-c304-5819-b013-a5b0152f048e'::uuid, '5fd16d27-a484-5313-9a94-cc1eff3f673b'::uuid, '*___ lo doy a mi hermano.*', 'mcq', '["Se","Le","Lo","Les"]'::jsonb, 0, '*Le lo* n’existe pas : devant *lo/la/los/las*, *le* devient *se*.', 2),
    ('1e3dc3ae-8bb4-581d-ab7f-d5efc027b6af'::uuid, '5fd16d27-a484-5313-9a94-cc1eff3f673b'::uuid, 'Avec un impératif affirmatif, le pronom se soude derrière le verbe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Dámelo*, *dímelo* — et l’accent écrit apparaît.', 3),
    ('8352bdcf-f112-53c8-afd7-ee821c3c390e'::uuid, '5fd16d27-a484-5313-9a94-cc1eff3f673b'::uuid, 'Où se place le pronom avec un impératif négatif ?', 'mcq', '["Devant le verbe","Soudé derrière","Après le sujet","En fin de phrase"]'::jsonb, 0, '*No me lo des* : l’enclise ne vaut que pour l’affirmatif.', 4),
    ('c46cb77a-2afe-55f3-8247-e7d1eb062ed0'::uuid, '5fd16d27-a484-5313-9a94-cc1eff3f673b'::uuid, '« Voy a decírtelo » et « Te lo voy a decir » sont tous deux corrects.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec un verbe conjugué + infinitif, les deux placements sont admis.', 5),
    ('7d25914f-aa47-56a6-86f5-04315e445f46'::uuid, '5fd16d27-a484-5313-9a94-cc1eff3f673b'::uuid, 'Quel pronom COD correspond à « la » (féminin) ?', 'mcq', '["La","Le","Se","Ella"]'::jsonb, 0, '*La veo* : je la vois. *Le hablo* serait un COI.', 6),
    ('a77899d1-7a08-5012-b5fc-f0b3c242382a'::uuid, '5fd16d27-a484-5313-9a94-cc1eff3f673b'::uuid, 'Le redoublement du COI est une lourdeur à éviter.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la norme : *Le doy el libro a Juan*, *A mí me gusta*.', 7),
    ('9ce87a22-5df5-5e83-89b9-8f133fecb3b3'::uuid, '5fd16d27-a484-5313-9a94-cc1eff3f673b'::uuid, 'L’accent écrit sur « dámelo » sert à…', 'mcq', '["Conserver la syllabe tonique du verbe d’origine","Marquer l’impératif","Distinguer le COD du COI","Signaler un pluriel"]'::jsonb, 0, 'L’enclise allonge le mot : sans accent, la prononciation changerait.', 8),
    ('4c159d17-6f62-51f9-be76-4405c27482e0'::uuid, 'bfa60e09-501a-5ade-9fef-bcb72ee185e9'::uuid, 'Avec quoi le possessif espagnol s’accorde-t-il ?', 'mcq', '["Avec ce qui est possédé","Avec le possesseur","Avec le verbe","Avec l’article"]'::jsonb, 0, '*Mis libros* : le -s vient des livres, pas de moi.', 1),
    ('0c2a1086-2bf9-5ccc-bec1-8bed5635ec88'::uuid, 'bfa60e09-501a-5ade-9fef-bcb72ee185e9'::uuid, '*Me lavo ___ manos.*', 'mcq', '["las","mis","sus","unas"]'::jsonb, 0, 'Le pronom réfléchi dit déjà à qui sont les mains : l’espagnol met l’ARTICLE.', 2),
    ('ee5af81e-ec8d-5466-9546-0fbe55028c3d'::uuid, 'bfa60e09-501a-5ade-9fef-bcb72ee185e9'::uuid, '« Su » peut signifier son, sa, leur ou votre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'D’où le recours à *de él*, *de usted* pour lever l’ambiguïté.', 3),
    ('67fa732f-b1d3-5865-8760-3ef04df5f4cc'::uuid, 'bfa60e09-501a-5ade-9fef-bcb72ee185e9'::uuid, 'Comment dit-on « un ami à moi » ?', 'mcq', '["Un amigo mío","Un mi amigo","Un amigo de mí","Mi un amigo"]'::jsonb, 0, 'La forme tonique se place après le nom.', 4),
    ('1981f5a6-68e6-56f0-90be-2ea97e55d47e'::uuid, 'bfa60e09-501a-5ade-9fef-bcb72ee185e9'::uuid, 'Quelles formes atones varient en genre ?', 'mcq', '["Nuestro et vuestro","Mi et tu","Su seulement","Toutes"]'::jsonb, 0, '*Nuestra casa*, *vuestros libros* — mais *mi* et *tu* restent invariables.', 5),
    ('3aeb5632-2f30-5025-9395-665f53a3a72c'::uuid, 'bfa60e09-501a-5ade-9fef-bcb72ee185e9'::uuid, '« El mío » est un pronom possessif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Article + forme tonique : *El mío es más grande.*', 6),
    ('426a46da-a1db-5a49-b6f2-c24a135eedad'::uuid, 'bfa60e09-501a-5ade-9fef-bcb72ee185e9'::uuid, '*Le duele ___ cabeza.*', 'mcq', '["la","su","una","esa"]'::jsonb, 0, 'Même logique qu’avec *lavarse* : article, pas possessif.', 7),
    ('9066d4a9-d395-5762-800e-f9bc1442ef83'::uuid, 'bfa60e09-501a-5ade-9fef-bcb72ee185e9'::uuid, 'Au vocatif, on dit « ¡Hijo mío! ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La forme tonique suit le nom en apostrophe : *¡Madre mía!*', 8),
    ('e8a2e984-9577-502e-8ae5-227978566c54'::uuid, '5b9e1926-2405-5297-b2fe-491a221f2a04'::uuid, 'Avec quoi « cuyo » s’accorde-t-il ?', 'mcq', '["Avec ce qui est possédé","Avec le possesseur","Avec le verbe","Il est invariable"]'::jsonb, 0, '*El escritor cuya novela leí* : *cuya* s’accorde avec *novela*.', 1),
    ('4be645b9-1276-5492-8485-22feae9e50c8'::uuid, '5b9e1926-2405-5297-b2fe-491a221f2a04'::uuid, '« Cuyo » peut être suivi d’un article.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Cuyo el libro » n’existe pas : *cuyo libro* directement.', 2),
    ('2001340c-f15f-5064-8524-5d83360a309b'::uuid, '5b9e1926-2405-5297-b2fe-491a221f2a04'::uuid, '*La chica con ___ hablo es mi prima.*', 'mcq', '["quien","que","cuyo","donde"]'::jsonb, 0, 'Après préposition et pour une personne : *quien*.', 3),
    ('da4ad865-03d5-52f1-bff5-75fa7f48cd8d'::uuid, '5b9e1926-2405-5297-b2fe-491a221f2a04'::uuid, 'Comment traduire « la maison dans laquelle je vis » ?', 'mcq', '["La casa en la que vivo","La casa que vivo","La casa cuya vivo","La casa quien vivo"]'::jsonb, 0, 'Après préposition, *que* prend l’article.', 4),
    ('2d1ba32b-5a4a-55f7-a63e-e63f161f6243'::uuid, '5b9e1926-2405-5297-b2fe-491a221f2a04'::uuid, 'Pour reprendre une idée entière, on emploie « lo que » ou « lo cual ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Llegó tarde, lo que me molestó.*', 5),
    ('5ab881d4-94bf-56e1-81c5-e3dec4a8644b'::uuid, '5b9e1926-2405-5297-b2fe-491a221f2a04'::uuid, '« Los que quieran, que vengan » signifie…', 'mcq', '["Que ceux qui veulent viennent","Ceux-là veulent venir","Ils veulent qu’ils viennent","Que veulent-ils venir"]'::jsonb, 0, '*El que / los que* sans antécédent = celui qui / ceux qui.', 6),
    ('9985a45f-cb91-5fdb-b431-c62ae6be293e'::uuid, '5b9e1926-2405-5297-b2fe-491a221f2a04'::uuid, '*¿___ es este libro?* — « à qui est-ce ? »', 'mcq', '["De quién","Cuyo","Qué de","Quién de"]'::jsonb, 0, '*Cuyo* ne s’emploie JAMAIS en question : c’est un relatif.', 7),
    ('768c9f5f-a60f-5c80-9f7d-2301b7e6a392'::uuid, '5b9e1926-2405-5297-b2fe-491a221f2a04'::uuid, '« El cual » appartient à un registre plus soutenu que « que ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Surtout après une préposition longue : *la razón por la cual*.', 8),
    ('1c914fd9-38ea-537e-b78d-c490a96b212e'::uuid, 'f482cd05-37ef-5c2c-ad53-b83b12f1ffe5'::uuid, 'Comment traduire « je ne vois personne » ?', 'mcq', '["No veo a nadie","No veo nadie","Veo a nadie","No veo alguien"]'::jsonb, 0, 'Double négation, et le *a* devant un COD de personne.', 1),
    ('562c1d39-5b7c-5a87-8287-5d5056dfa662'::uuid, 'f482cd05-37ef-5c2c-ad53-b83b12f1ffe5'::uuid, '« Cualquiera » s’apocope en « cualquier » devant un nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Masculin comme féminin : *cualquier día*, *cualquier mujer*.', 2),
    ('51c93605-77b6-5827-b0fe-c747ec0f4db3'::uuid, 'f482cd05-37ef-5c2c-ad53-b83b12f1ffe5'::uuid, '« Cada » peut-il se mettre au pluriel ?', 'mcq', '["Non, il est invariable","Oui : cadas","Oui au féminin seulement","Oui devant un nombre"]'::jsonb, 0, '*Cada día*, *cada dos horas* ; « chacun » se dit *cada uno*.', 3),
    ('9838a791-3fdf-5acf-97d6-3f5661486e98'::uuid, 'f482cd05-37ef-5c2c-ad53-b83b12f1ffe5'::uuid, 'Placé après le nom, « alguno » prend un sens…', 'mcq', '["Négatif renforcé","Positif renforcé","Interrogatif","Neutre"]'::jsonb, 0, '*No tengo duda alguna* = aucun doute.', 4),
    ('48dd93ef-1cb0-50ef-ae83-7e6a59fb8d25'::uuid, 'f482cd05-37ef-5c2c-ad53-b83b12f1ffe5'::uuid, '« Todos días » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Todo* exige l’article : *todos los días*.', 5),
    ('c48a5c6d-d58e-581a-8e78-e29383444629'::uuid, 'f482cd05-37ef-5c2c-ad53-b83b12f1ffe5'::uuid, 'Que signifie « los demás » ?', 'mcq', '["Les autres, le reste","Les mêmes","Trop nombreux","Chacun"]'::jsonb, 0, '*Los demás alumnos se fueron.*', 6),
    ('d30d2d6c-8101-547b-bdab-fac141fd7c6e'::uuid, 'f482cd05-37ef-5c2c-ad53-b83b12f1ffe5'::uuid, '« Alguien » et « nadie » sont invariables et toujours singuliers.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils ne s’accordent ni en genre ni en nombre.', 7),
    ('61780811-aecf-547c-aa5a-acc2ed879bd1'::uuid, 'f482cd05-37ef-5c2c-ad53-b83b12f1ffe5'::uuid, 'Comment dit-on « un autre livre » ?', 'mcq', '["Otro libro","Un otro libro","El otro libro","Otro el libro"]'::jsonb, 0, '*Otro* ne prend jamais l’article indéfini.', 8),
    ('ec077371-4b0b-5976-9418-52dd8d3f86a3'::uuid, '1672660d-7bab-592d-a69f-36ab886f6385'::uuid, '*Es ___ alto como tú.*', 'mcq', '["tan","tanto","más","muy"]'::jsonb, 0, '*Tan* devant un adjectif, *tanto* devant un nom.', 1),
    ('54629143-1359-5ef2-bd5b-c1467ed9a2cd'::uuid, '1672660d-7bab-592d-a69f-36ab886f6385'::uuid, '*Tengo ___ libros como tú.*', 'mcq', '["tantos","tan","tanto","más"]'::jsonb, 0, 'Devant un nom, *tanto* s’accorde : *tantos libros*.', 2),
    ('fedc1315-a7ef-5190-92f0-5f0bb2f9ddc1'::uuid, '1672660d-7bab-592d-a69f-36ab886f6385'::uuid, 'Devant un nombre, on emploie « de » et non « que ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Más de veinte libros*, *menos de diez euros*.', 3),
    ('edd7c080-b37a-5b87-8daf-9ddec0bb5bbe'::uuid, '1672660d-7bab-592d-a69f-36ab886f6385'::uuid, 'Que signifie « No tengo más que diez euros » ?', 'mcq', '["Je n’ai que dix euros","Je n’ai pas plus de dix euros","J’ai plus de dix euros","J’ai environ dix euros"]'::jsonb, 0, 'En phrase négative, *más que* signifie « seulement ».', 4),
    ('8d78586d-2501-5196-9122-b5be3cb39bd6'::uuid, '1672660d-7bab-592d-a69f-36ab886f6385'::uuid, '« Más mejor » est correct en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les comparatifs irréguliers ne se combinent jamais avec *más*.', 5),
    ('444763ee-3528-5e59-87b7-8f50dd8dbad6'::uuid, '1672660d-7bab-592d-a69f-36ab886f6385'::uuid, '*Este resultado es ___ que el anterior.*', 'mcq', '["peor","más malo","menor","mal"]'::jsonb, 0, 'Comparatif irrégulier, comme *bueno → mejor*.', 6),
    ('9bb1f27a-00b4-5b40-a3b3-8bc179ed8a30'::uuid, '1672660d-7bab-592d-a69f-36ab886f6385'::uuid, 'Comment traduire « plus difficile qu’il n’y paraît » ?', 'mcq', '["Más difícil de lo que parece","Más difícil que parece","Más difícil como parece","Tan difícil que parece"]'::jsonb, 0, 'Quand le second terme est une proposition : *de lo que*.', 7),
    ('ec2d1a24-3816-5ee4-8033-89f3dcd81824'::uuid, '1672660d-7bab-592d-a69f-36ab886f6385'::uuid, '« Trabaja tanto como yo » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Après un verbe, on emploie *tanto como*, invariable.', 8),
    ('6d9254f2-763e-5184-964c-573b427040a7'::uuid, 'e35de697-cdfd-51cf-8b70-7460ecb4f5fb'::uuid, '*Es el edificio más alto ___ mundo.*', 'mcq', '["del","en el","de el","al"]'::jsonb, 0, 'Le complément du superlatif se met avec *de*, jamais *en* — et *de + el* se contracte.', 1),
    ('82884534-3a65-583f-ba88-7fe8acda73b2'::uuid, 'e35de697-cdfd-51cf-8b70-7460ecb4f5fb'::uuid, '« Muy guapísimo » est une tournure correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On emploie *muy* OU le suffixe -ísimo, jamais les deux.', 2),
    ('30dcbf05-6646-5ebe-a135-04facb4e999e'::uuid, 'e35de697-cdfd-51cf-8b70-7460ecb4f5fb'::uuid, '*Es un país ___* — « très riche ».', 'mcq', '["riquísimo","ricísimo","rikísimo","ricoísimo"]'::jsonb, 0, 'Le *c* devient *qu* devant le suffixe pour garder le son [k].', 3),
    ('6d5fe997-2e45-5134-acbc-01c9fb98d5a7'::uuid, 'e35de697-cdfd-51cf-8b70-7460ecb4f5fb'::uuid, 'Quel est le superlatif absolu de « feliz » ?', 'mcq', '["Felicísimo","Felizísimo","Felisísimo","Felizmo"]'::jsonb, 0, 'Le z devient c devant le i.', 4),
    ('40ac77e1-e5d5-5461-b8d6-09e843e6558d'::uuid, 'e35de697-cdfd-51cf-8b70-7460ecb4f5fb'::uuid, '« Óptimo » est le superlatif savant de « bueno ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme *pésimo* pour *malo*, *máximo* pour *grande*.', 5),
    ('0e571985-9950-5023-a015-3572895e32bd'::uuid, 'e35de697-cdfd-51cf-8b70-7460ecb4f5fb'::uuid, 'Que devient le « g » de « largo » au superlatif ?', 'mcq', '["Il devient gu : larguísimo","Il disparaît","Il devient j","Il double"]'::jsonb, 0, 'Pour conserver le son [g] devant le i.', 6),
    ('dbb90be7-ed91-5e54-b82d-a03f6dabe871'::uuid, 'e35de697-cdfd-51cf-8b70-7460ecb4f5fb'::uuid, 'Le superlatif relatif compare à l’intérieur d’un ensemble.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*El alumno más inteligente de la clase* : l’ensemble est la classe.', 7),
    ('c1b1789c-a4f9-52fe-a6f8-67afacda5897'::uuid, 'e35de697-cdfd-51cf-8b70-7460ecb4f5fb'::uuid, 'Comment dit-on « énormément » avec un suffixe ?', 'mcq', '["Muchísimo","Muy mucho","Mucho muy","Máximo"]'::jsonb, 0, '*Mucho* prend lui aussi le suffixe -ísimo.', 8),
    ('b981fb2c-93da-55b2-a3eb-53a917aec4da'::uuid, 'fc73d3f6-d5f2-50a4-964c-6c430b093615'::uuid, '*Es un ___ amigo.*', 'mcq', '["buen","bueno","buena","bue"]'::jsonb, 0, '*Bueno* s’apocope en *buen* devant un nom masculin singulier.', 1),
    ('e20f5af7-aadf-59bd-9c37-a7b920e91d99'::uuid, 'fc73d3f6-d5f2-50a4-964c-6c430b093615'::uuid, '« Grande » s’apocope devant un nom féminin singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Una gran mujer* : c’est le seul adjectif à s’apocoper aux deux genres.', 2),
    ('0d00f7c4-25b0-5dca-911e-ff90254695a4'::uuid, 'fc73d3f6-d5f2-50a4-964c-6c430b093615'::uuid, '*Cuesta ___ euros.*', 'mcq', '["cien","ciento","cientos","cienes"]'::jsonb, 0, '*Ciento* s’apocope en *cien* devant un nom : *cien euros*, mais *ciento veinte*.', 3),
    ('ca915056-c1ac-5257-883d-104f757d1641'::uuid, 'fc73d3f6-d5f2-50a4-964c-6c430b093615'::uuid, 'Quelle est la forme correcte : « santo Domingo » ou « Santo Domingo » ?', 'mcq', '["Santo Domingo : pas d’apocope devant To- et Do-","San Domingo","Sant Domingo","Sa Domingo"]'::jsonb, 0, 'Même exception pour *Santo Tomás* et *Santo Tomé*.', 4),
    ('a97103ee-27ae-53a7-948e-0ac6f55f89b8'::uuid, 'fc73d3f6-d5f2-50a4-964c-6c430b093615'::uuid, '« Tercero » devient « tercer » devant un nom masculin singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*El tercer año*, comme *el primer piso*.', 5),
    ('34ecc11c-3463-5870-93a7-d91945d87560'::uuid, 'fc73d3f6-d5f2-50a4-964c-6c430b093615'::uuid, 'Quelle est la forme apocopée de « cualquiera » ?', 'mcq', '["Cualquier, aux deux genres","Cualqui","Cualquiero","Il ne s’apocope pas"]'::jsonb, 0, '*Cualquier día*, *cualquier mujer*.', 6),
    ('0095e688-2b21-5b1f-b9a5-713f3428ee1d'::uuid, 'fc73d3f6-d5f2-50a4-964c-6c430b093615'::uuid, '« Recién » s’emploie devant un participe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Recién nacido*, *recién llegado*, *recién casados*.', 7),
    ('5be99038-8ae5-56d1-b4af-a66c8d546df2'::uuid, 'fc73d3f6-d5f2-50a4-964c-6c430b093615'::uuid, '« Ciento veinte » garde la forme pleine parce que…', 'mcq', '["Ciento est suivi d’un autre nombre","Ciento est féminin","Le nombre est pair","Il s’agit d’un pluriel"]'::jsonb, 0, 'L’apocope ne joue que devant un nom, *mil* ou *millones*.', 8),
    ('11b35f30-e465-5661-b18a-f28d85534e6e'::uuid, '287fa7d9-d040-5a4f-a846-955a2c24ca19'::uuid, 'Combien l’espagnol a-t-il d’auxiliaires de temps composés ?', 'mcq', '["Un seul : haber","Deux : haber et ser","Deux : haber et tener","Trois"]'::jsonb, 0, 'Contrairement au français, aucune hésitation entre « être » et « avoir ».', 1),
    ('7b598524-09a5-51d6-8bfd-666f3b1f3019'::uuid, '287fa7d9-d040-5a4f-a846-955a2c24ca19'::uuid, 'Le participe passé s’accorde avec « haber ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Jamais : *la carta que he escrito*, *ellas han venido*.', 2),
    ('8792e540-1326-5603-83ad-2af2d14986ad'::uuid, '287fa7d9-d040-5a4f-a846-955a2c24ca19'::uuid, 'Comment traduire « il y a deux livres » ?', 'mcq', '["Hay dos libros","Han dos libros","Hays dos libros","Están dos libros"]'::jsonb, 0, '*Hay* est invariable, même devant un pluriel.', 3),
    ('0c9acfd6-b34c-555c-bbad-649a3088bdba'::uuid, '287fa7d9-d040-5a4f-a846-955a2c24ca19'::uuid, 'Peut-on placer un adverbe entre l’auxiliaire et le participe ?', 'mcq', '["Non, le bloc est soudé","Oui, toujours","Oui, si c’est une négation","Oui, à l’écrit seulement"]'::jsonb, 0, '*No lo he visto nunca*, jamais « he nunca visto ».', 4),
    ('7c44d75b-cde9-51b1-b6a6-e3826eb02c2b'::uuid, '287fa7d9-d040-5a4f-a846-955a2c24ca19'::uuid, '« Había » est la forme passée de « hay ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et elle reste au singulier : *Había muchos alumnos.*', 5),
    ('e9bcf727-f549-5591-acbe-0a95fd81167e'::uuid, '287fa7d9-d040-5a4f-a846-955a2c24ca19'::uuid, 'Que signifie « Hay que estudiar » ?', 'mcq', '["Il faut étudier","J’ai étudié","Il y a des études","Il faut que j’étudie"]'::jsonb, 0, 'Obligation impersonnelle, sans sujet exprimé.', 6),
    ('c7ea7d11-3f99-51eb-805e-56cdf6fd920f'::uuid, '287fa7d9-d040-5a4f-a846-955a2c24ca19'::uuid, 'Comment forme-t-on le plus-que-parfait ?', 'mcq', '["Había + participe passé","Hubo + participe passé","Era + participe passé","Estaba + participe passé"]'::jsonb, 0, '*Había salido cuando llegué.*', 7),
    ('a690b8da-ecfc-5594-9cbf-d2e1ba6844af'::uuid, '287fa7d9-d040-5a4f-a846-955a2c24ca19'::uuid, '« Hay un banco en la plaza » et « El banco está en la plaza » disent la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Hay* pose l’existence, *estar* localise une chose déjà connue.', 8),
    ('8ca3e36b-b20c-5aee-950b-3c08990bc181'::uuid, 'c216f5fa-5330-51e3-b93b-e68a35fd7073'::uuid, 'Où se place le pronom réfléchi avec un infinitif ?', 'mcq', '["Soudé derrière : levantarse","Devant l’infinitif","En fin de phrase","Devant le sujet"]'::jsonb, 0, 'Même chose au gérondif et à l’impératif affirmatif.', 1),
    ('5ff0acd6-7a71-52a5-aeb5-e06e989aca0f'::uuid, 'c216f5fa-5330-51e3-b93b-e68a35fd7073'::uuid, 'Dans « Se venden pisos », le verbe s’accorde avec « pisos ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un *se* passif : le sujet grammatical est *pisos*.', 2),
    ('868b5f58-48c8-5c77-9430-234d56da4901'::uuid, 'c216f5fa-5330-51e3-b93b-e68a35fd7073'::uuid, 'Que signifie « Me voy » ?', 'mcq', '["Je m’en vais","Je vais bien","Je me vois","Je viens"]'::jsonb, 0, '*Ir* signifie aller, *irse* partir : le pronom change le sens.', 3),
    ('bbf621bb-b18e-5097-85e1-b77223ecb95b'::uuid, 'c216f5fa-5330-51e3-b93b-e68a35fd7073'::uuid, 'Dans un « se » impersonnel, le verbe est…', 'mcq', '["Toujours au singulier","Toujours au pluriel","Accordé au complément","À l’infinitif"]'::jsonb, 0, '*Se dice que…*, *Aquí se come bien.*', 4),
    ('8eaf83ee-575a-5a73-a5b3-6a7d538f3581'::uuid, 'c216f5fa-5330-51e3-b93b-e68a35fd7073'::uuid, '« Quejarse » et « atreverse » sont des verbes essentiellement pronominaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le pronom fait partie du verbe : il n’a pas de valeur réfléchie.', 5),
    ('1b8d8181-6b17-588b-a723-e0968379b473'::uuid, 'c216f5fa-5330-51e3-b93b-e68a35fd7073'::uuid, 'Que signifie « Se escriben » ?', 'mcq', '["Ils s’écrivent l’un à l’autre","Ils s’écrivent eux-mêmes","On les écrit","Ils sont écrits"]'::jsonb, 0, 'Valeur réciproque : plusieurs sujets agissent l’un sur l’autre.', 6),
    ('600713b5-d659-5e64-bb48-d404aba8eead'::uuid, 'c216f5fa-5330-51e3-b93b-e68a35fd7073'::uuid, '« Dormirse » signifie « s’endormir ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Alors que *dormir* signifie simplement dormir.', 7),
    ('a8b9c65f-d26b-5280-ab3d-838de091ccc0'::uuid, 'c216f5fa-5330-51e3-b93b-e68a35fd7073'::uuid, 'Dans « Se comió toda la tarta », le pronom exprime…', 'mcq', '["Une nuance d’appropriation","Une réciprocité","Une passive","Une obligation"]'::jsonb, 0, 'Le pronominal d’intensité, sans valeur réfléchie.', 8),
    ('8f6a8d00-1f14-5210-b409-856a20d97e6c'::uuid, 'bc57577b-e298-5f92-bc02-a3a14d06f9f4'::uuid, 'Qu’est-ce qui déclenche la diphtongue ?', 'mcq', '["L’accent tonique sur la voyelle du radical","La terminaison en -ar","Le pluriel","La négation"]'::jsonb, 0, 'Quand l’accent passe sur la terminaison, la voyelle redevient simple.', 1),
    ('97864da3-0f5b-553e-9daa-5f6ec6307f9d'::uuid, 'bc57577b-e298-5f92-bc02-a3a14d06f9f4'::uuid, 'Quelles personnes ne diphtonguent jamais ?', 'mcq', '["Nosotros et vosotros","Yo et tú","Él et ellos","Tú et vosotros"]'::jsonb, 0, 'Elles portent l’accent sur la terminaison : d’où la conjugaison « en botte ».', 2),
    ('5517d7e8-2734-5c7d-b7c1-201a7b1c9e4b'::uuid, 'bc57577b-e298-5f92-bc02-a3a14d06f9f4'::uuid, 'Quelle est la première personne de « poder » au présent ?', 'mcq', '["Puedo","Podo","Puedo/podo","Puedes"]'::jsonb, 0, 'La diphtongue o → ue apparaît sous l’accent.', 3),
    ('e8e0bb74-814f-5b19-9492-8b81073acbf8'::uuid, 'bc57577b-e298-5f92-bc02-a3a14d06f9f4'::uuid, '« Jugar » est le seul verbe à diphtonguer u → ue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Juego, juegas, juega… jugamos, jugáis, juegan.*', 4),
    ('b96e328c-6b3b-557c-afe6-1eab3ce9dcef'::uuid, 'bc57577b-e298-5f92-bc02-a3a14d06f9f4'::uuid, 'La diphtongue apparaît aussi au passé simple.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seulement au présent de l’indicatif, au subjonctif présent et à l’impératif.', 5),
    ('4c149a7f-0c39-550f-b12e-3254012a3a01'::uuid, 'bc57577b-e298-5f92-bc02-a3a14d06f9f4'::uuid, 'Quelle est la forme de « pensar » à la première personne du pluriel ?', 'mcq', '["Pensamos","Piensamos","Pensemos","Piensemos"]'::jsonb, 0, 'L’accent tombe sur la terminaison : pas de diphtongue.', 6),
    ('a3704f92-a20b-566d-bc10-558300dadd62'::uuid, 'bc57577b-e298-5f92-bc02-a3a14d06f9f4'::uuid, 'Que devient « oler » quand il diphtongue ?', 'mcq', '["Huelo, avec un h","Uelo","Ólo","Oigo"]'::jsonb, 0, 'Un h purement orthographique s’ajoute devant le ue initial.', 7),
    ('674a5adc-42eb-50b1-aa4c-8a06282eb8d4'::uuid, 'bc57577b-e298-5f92-bc02-a3a14d06f9f4'::uuid, '« Pedir → pido » est un verbe à diphtongue.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un verbe à affaiblissement : le e devient i, il ne diphtongue pas.', 8),
    ('f00fc7fb-24ea-54ee-9efa-05bc5a027890'::uuid, '15285cfa-a694-5758-a0ff-590f1987f541'::uuid, 'À quel groupe appartiennent tous les verbes à affaiblissement ?', 'mcq', '["Aux verbes en -ir","Aux verbes en -ar","Aux verbes en -er","À tous les groupes"]'::jsonb, 0, '*Pedir, servir, repetir, seguir…* — aucun -ar ni -er.', 1),
    ('0c7c356f-322c-5e20-9088-eb30642e86c1'::uuid, '15285cfa-a694-5758-a0ff-590f1987f541'::uuid, 'Quelle est la troisième personne du passé simple de « pedir » ?', 'mcq', '["Pidió","Pedió","Pidó","Pediró"]'::jsonb, 0, 'Dès que la terminaison contient un ió ou un ie, le e s’affaiblit.', 2),
    ('c992224e-fb17-5396-9881-25cd1d94d316'::uuid, '15285cfa-a694-5758-a0ff-590f1987f541'::uuid, 'Au subjonctif présent, l’affaiblissement touche toutes les personnes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Pida, pidas, pida, pidamos, pidáis, pidan* — y compris nosotros et vosotros.', 3),
    ('a82ec958-e5b1-584b-99e2-5fb37e8926c6'::uuid, '15285cfa-a694-5758-a0ff-590f1987f541'::uuid, 'Quel est le gérondif de « decir » ?', 'mcq', '["Diciendo","Deciendo","Diciento","Dicendo"]'::jsonb, 0, 'Le gérondif des verbes en -ir irréguliers porte l’affaiblissement.', 4),
    ('e3071ca1-84e3-5d0a-a711-448235424b88'::uuid, '15285cfa-a694-5758-a0ff-590f1987f541'::uuid, '« Dormir » est un verbe mixte : diphtongue au présent, affaiblissement ailleurs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Duermo* au présent, mais *durmió* et *durmiendo*.', 5),
    ('5c006494-7d81-5f83-9f88-19661eccbe47'::uuid, '15285cfa-a694-5758-a0ff-590f1987f541'::uuid, 'Quelle est la première personne du présent de « seguir » ?', 'mcq', '["Sigo","Siguo","Sego","Seguo"]'::jsonb, 0, 'Le u disparaît devant o et a, sinon il se prononcerait.', 6),
    ('7a1c712f-7657-5a91-9c85-6a96b251a0d0'::uuid, '15285cfa-a694-5758-a0ff-590f1987f541'::uuid, 'Que devient le « g » de « elegir » devant un o ?', 'mcq', '["Il devient j : elijo","Il devient gu","Il disparaît","Il double"]'::jsonb, 0, 'Pour conserver le son [x] : *elijo*, *corrijo*.', 7),
    ('b4d60098-37b2-59db-8d38-af445c8cef4b'::uuid, '15285cfa-a694-5758-a0ff-590f1987f541'::uuid, '« Pedimos » porte l’affaiblissement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Comme *pedís*, il garde le e : l’accent tombe sur la terminaison.', 8),
    ('7115954a-d8f6-5174-bea5-630d3f4aef02'::uuid, '826b329c-282b-56b4-90f4-0263a66f8cc7'::uuid, 'Quel verbe employer pour la localisation d’une chose ?', 'mcq', '["Estar","Ser","Haber","Tener"]'::jsonb, 0, '*Madrid está en España* — mais un événement se situe avec *ser*.', 1),
    ('07d3f71e-19f9-5340-9c71-957c5f41ffce'::uuid, '826b329c-282b-56b4-90f4-0263a66f8cc7'::uuid, '« Ser listo » et « estar listo » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Être malin » contre « être prêt » : deux mots différents.', 2),
    ('c4d3b205-a0cd-5fc5-8392-fc48d675f0e8'::uuid, '826b329c-282b-56b4-90f4-0263a66f8cc7'::uuid, 'Comment dit-on l’heure en espagnol ?', 'mcq', '["Son las tres","Están las tres","Hay las tres","Tienen las tres"]'::jsonb, 0, 'Heure, date, prix : toujours *ser*.', 3),
    ('1d7e5b8d-9426-5956-a891-651e11c41c8c'::uuid, '826b329c-282b-56b4-90f4-0263a66f8cc7'::uuid, 'Que signifie « estar malo » ?', 'mcq', '["Être malade","Être méchant","Être mauvais","Être en colère"]'::jsonb, 0, '*Ser malo* signifie être méchant.', 4),
    ('eb49fe2a-acb6-535f-b3d1-a728b9ef79cf'::uuid, '826b329c-282b-56b4-90f4-0263a66f8cc7'::uuid, '« La fiesta es en mi casa » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un événement se situe avec *ser*, à la différence d’un lieu ou d’un objet.', 5),
    ('4ad28a50-e7d2-568d-beda-50b412095bc4'::uuid, '826b329c-282b-56b4-90f4-0263a66f8cc7'::uuid, 'Quel verbe entre dans la forme progressive ?', 'mcq', '["Estar (estoy estudiando)","Ser","Haber","Ir"]'::jsonb, 0, '*Estar* + gérondif exprime l’action en cours.', 6),
    ('dee8c039-d055-5474-8b36-3adab894c011'::uuid, '826b329c-282b-56b4-90f4-0263a66f8cc7'::uuid, '« La sopa está fría » décrit un état constaté.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La soupe a refroidi ; *el hielo es frío* énonce une propriété.', 7),
    ('760a1e13-4b4f-5fa2-897b-2cfa99e74943'::uuid, '826b329c-282b-56b4-90f4-0263a66f8cc7'::uuid, 'Comment dit-on « je suis d’accord » ?', 'mcq', '["Estoy de acuerdo","Soy de acuerdo","Tengo de acuerdo","Hay de acuerdo"]'::jsonb, 0, 'Expression figée avec *estar*, comme *estar de vacaciones*.', 8),
    ('4aae0666-b3ba-5345-b22c-d601775cfffa'::uuid, '160674eb-7f6a-5edb-979f-f81425292eb8'::uuid, 'Quelle est la terminaison du gérondif des verbes en -ar ?', 'mcq', '["-ando","-iendo","-yendo","-ado"]'::jsonb, 0, '*Hablar → hablando* ; les -er et -ir font *-iendo*.', 1),
    ('a325d638-87ec-5d32-86d3-85727bdd0ed6'::uuid, '160674eb-7f6a-5edb-979f-f81425292eb8'::uuid, 'Quel est le gérondif de « leer » ?', 'mcq', '["Leyendo","Leiendo","Leendo","Leído"]'::jsonb, 0, 'Le -iendo devient -yendo après une voyelle.', 2),
    ('4245f3c6-7105-5578-b80e-881bfce6857a'::uuid, '160674eb-7f6a-5edb-979f-f81425292eb8'::uuid, '« Una caja conteniendo libros » est correct en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le gérondif ne qualifie pas un nom : *una caja que contiene libros*.', 3),
    ('5d29b355-77cd-5dd7-b070-c9f7d16f95e9'::uuid, '160674eb-7f6a-5edb-979f-f81425292eb8'::uuid, 'Que signifie « Llevo dos años estudiando español » ?', 'mcq', '["J’étudie l’espagnol depuis deux ans","J’ai étudié deux ans","J’emporte deux ans d’espagnol","Je vais étudier deux ans"]'::jsonb, 0, '*Llevar* + durée + gérondif exprime la durée écoulée.', 4),
    ('2a7c32c1-1bb2-5a77-88dd-7dd6b3f087d6'::uuid, '160674eb-7f6a-5edb-979f-f81425292eb8'::uuid, 'Après une préposition, on emploie l’infinitif et non le gérondif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Antes de salir*, *sin decir nada*, *al entrar*.', 5),
    ('33e90979-b264-5697-8bd7-8af01e9d7be6'::uuid, '160674eb-7f6a-5edb-979f-f81425292eb8'::uuid, 'Comment traduire « en entrant, j’ai vu Juan » ?', 'mcq', '["Al entrar, vi a Juan","Entrando, vi a Juan","En entrando, vi a Juan","Para entrar, vi a Juan"]'::jsonb, 0, '*Al* + infinitif exprime la simultanéité.', 6),
    ('8e92deb3-6c65-5fc6-8cfe-2fd21a078b4c'::uuid, '160674eb-7f6a-5edb-979f-f81425292eb8'::uuid, '« Sigue lloviendo » signifie « il pleut toujours ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Seguir* + gérondif exprime la continuation.', 7),
    ('d8d58b56-39a3-515c-b107-d58b3b2c2d28'::uuid, '160674eb-7f6a-5edb-979f-f81425292eb8'::uuid, 'Quel est le gérondif de « dormir » ?', 'mcq', '["Durmiendo","Dormiendo","Duermiendo","Durmendo"]'::jsonb, 0, 'L’affaiblissement o → u apparaît au gérondif des verbes en -ir.', 8),
    ('8e2544c0-26ec-5e34-b246-7484bdba04fc'::uuid, '464ad45a-8f2a-5095-a48d-6f70638886f9'::uuid, 'Le participe employé avec « haber » s’accorde-t-il ?', 'mcq', '["Jamais","Toujours","Seulement au féminin","Seulement au pluriel"]'::jsonb, 0, '*Ellas han llegado*, *las cartas que he escrito*.', 1),
    ('73b9507a-3f59-559f-ae69-aeb6c1ad30ed'::uuid, '464ad45a-8f2a-5095-a48d-6f70638886f9'::uuid, 'Quel est le participe passé de « escribir » ?', 'mcq', '["Escrito","Escribido","Escribado","Escripto"]'::jsonb, 0, 'Comme *abrir → abierto*, *hacer → hecho*, *ver → visto*.', 2),
    ('a3b98786-d147-58f7-b5ba-dd51535f6fb5'::uuid, '464ad45a-8f2a-5095-a48d-6f70638886f9'::uuid, '« La puerta está cerrada » comporte un accord.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec *estar*, le participe s’accorde avec le sujet.', 3),
    ('41e22208-4def-50c6-a47f-2818fd916034'::uuid, '464ad45a-8f2a-5095-a48d-6f70638886f9'::uuid, 'Quelle différence entre « fue construida » et « está construida » ?', 'mcq', '["La première décrit l’action, la seconde l’état résultant","Aucune","La première est un futur","La seconde est un passé simple"]'::jsonb, 0, '*Ser* + participe = passive d’action ; *estar* + participe = état.', 4),
    ('b2e42a25-fe83-58fe-bbe8-e6ec3ce3f184'::uuid, '464ad45a-8f2a-5095-a48d-6f70638886f9'::uuid, 'Quel est le participe passé de « volver » ?', 'mcq', '["Vuelto","Volvido","Volvido/vuelto","Voltado"]'::jsonb, 0, 'Comme *resolver → resuelto*, *poner → puesto*.', 5),
    ('f5a65e4e-7098-59eb-afdf-cbe1169553df'::uuid, '464ad45a-8f2a-5095-a48d-6f70638886f9'::uuid, 'L’espagnol emploie la passive avec « ser » plus souvent que le français.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il lui préfère la tournure *se* ou la 3e personne du pluriel.', 6),
    ('e165626f-90ee-5655-a1f2-5367f1a088e5'::uuid, '464ad45a-8f2a-5095-a48d-6f70638886f9'::uuid, 'Quel participe emploie-t-on comme adjectif avec « freír » ?', 'mcq', '["Frito (patatas fritas)","Freído","Freito","Fritado"]'::jsonb, 0, 'Participe double : *he freído* aux temps composés, *frito* comme adjectif.', 7),
    ('59ae6172-62b0-50cc-a03b-93075986a333'::uuid, '464ad45a-8f2a-5095-a48d-6f70638886f9'::uuid, 'Quel est le participe passé de « satisfacer » ?', 'mcq', '["Satisfecho","Satisfacido","Satisfaído","Satisfacto"]'::jsonb, 0, 'Formé sur *hacer → hecho*.', 8),
    ('5fe467db-64d0-5e16-9d93-1dcf0bc22214'::uuid, '6d32489f-4b63-5981-a73b-efa5dd7a20ae'::uuid, 'Dans « Me gustan las películas », quel est le sujet ?', 'mcq', '["Las películas","Me","Yo","Gustan"]'::jsonb, 0, 'Le verbe s’accorde avec ce qui plaît, pas avec la personne.', 1),
    ('509f1aeb-0b2b-5d90-86f9-34b5175b5df5'::uuid, '6d32489f-4b63-5981-a73b-efa5dd7a20ae'::uuid, 'Comment traduire « j’aime lire et écrire » ?', 'mcq', '["Me gusta leer y escribir","Me gustan leer y escribir","Yo gusto leer y escribir","Me gusto leer y escribir"]'::jsonb, 0, 'Un ou plusieurs infinitifs comptent pour un singulier.', 2),
    ('e3d90b7b-19ae-528c-9b0f-dec96dc9444d'::uuid, '6d32489f-4b63-5981-a73b-efa5dd7a20ae'::uuid, '« A mí me gusta » est une redondance à éviter.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la norme : le *a mí* renforce, le pronom *me* reste obligatoire.', 3),
    ('5a616b02-252c-5793-bb82-d18cbf4ebe0b'::uuid, '6d32489f-4b63-5981-a73b-efa5dd7a20ae'::uuid, 'Comment traduire « j’ai mal à la tête » ?', 'mcq', '["Me duele la cabeza","Duelo la cabeza","Tengo dolor la cabeza","Me duelo la cabeza"]'::jsonb, 0, '*Doler* se construit comme *gustar*.', 4),
    ('df2d02c2-10cd-510d-831b-ce3e7faffa1e'::uuid, '6d32489f-4b63-5981-a73b-efa5dd7a20ae'::uuid, 'Que répondre à « Me gusta el cine » pour dire « moi aussi » ?', 'mcq', '["A mí también","A mí tampoco","A mí sí","Yo también gusto"]'::jsonb, 0, '*Tampoco* servirait à répondre à une phrase négative.', 5),
    ('47dc775e-6390-59a3-a768-0838c7b4b218'::uuid, '6d32489f-4b63-5981-a73b-efa5dd7a20ae'::uuid, '« Me encantan los perros » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Encantar* fonctionne comme *gustar* : accord avec *los perros*.', 6),
    ('386a1f7b-47bd-5130-83bb-9b07335e0645'::uuid, '6d32489f-4b63-5981-a73b-efa5dd7a20ae'::uuid, 'Comment renforcer « le gusta » pour préciser qu’il s’agit de Juan ?', 'mcq', '["A Juan le gusta","Juan le gusta","Le gusta Juan","A Juan gusta"]'::jsonb, 0, 'Le pronom *le* se maintient même quand le nom est exprimé.', 7),
    ('29b154e4-3017-5c2a-ab70-83e9e34a6e2a'::uuid, '6d32489f-4b63-5981-a73b-efa5dd7a20ae'::uuid, 'On peut dire « me gusta muy ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On dit *me gusta mucho* : *muy* ne modifie jamais un verbe.', 8),
    ('a8d92018-f1b2-59bf-b85e-b2cc9bc40c0c'::uuid, '65a0fc6d-f5b2-52ba-ae86-b9df5e06dbe5'::uuid, 'Quelle tournure exprime une obligation personnelle ?', 'mcq', '["Tener que + infinitif","Hay que + infinitif","Soler + infinitif","Acabar de + infinitif"]'::jsonb, 0, '*Tengo que estudiar* : l’obligation vise quelqu’un.', 1),
    ('f3cac5d5-5326-54f5-86ae-cfe99e0e34bb'::uuid, '65a0fc6d-f5b2-52ba-ae86-b9df5e06dbe5'::uuid, '« Hay que » est invariable.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’obligation est impersonnelle : aucun sujet, donc aucune variation en personne.', 2),
    ('a9c762bb-f457-55d9-b015-3dc24c508e0f'::uuid, '65a0fc6d-f5b2-52ba-ae86-b9df5e06dbe5'::uuid, 'Que signifie « Debe de estar enfermo » ?', 'mcq', '["Il doit être malade (supposition)","Il doit rester malade","Il faut qu’il soit malade","Il a dû tomber malade"]'::jsonb, 0, '*Deber de* exprime la probabilité, *deber* seul l’obligation morale.', 3),
    ('2c56b501-6df9-5129-ab8e-acd09738371e'::uuid, '65a0fc6d-f5b2-52ba-ae86-b9df5e06dbe5'::uuid, 'Comment traduire « il faut étudier » (en général) ?', 'mcq', '["Hay que estudiar","Tengo que estudiar","Debo estudiar","Es estudiar"]'::jsonb, 0, 'L’obligation impersonnelle passe par *hay que*.', 4),
    ('70b42c16-a112-5353-bbd5-baf10977b441'::uuid, '65a0fc6d-f5b2-52ba-ae86-b9df5e06dbe5'::uuid, 'Après « Es necesario que », le verbe est au subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Es necesario que vengas* : le jugement impersonnel commande le subjonctif.', 5),
    ('5e0cfdd9-999d-518b-bf00-e8b9156629b8'::uuid, '65a0fc6d-f5b2-52ba-ae86-b9df5e06dbe5'::uuid, 'Quelle nuance sépare « tenía que estudiar » et « tuve que estudiar » ?', 'mcq', '["L’imparfait laisse ouvert, le passé simple conclut","Aucune","Le premier est un futur","Le second est impersonnel"]'::jsonb, 0, '*Tuve que* dit que l’obligation a été suivie d’effet.', 6),
    ('c89004d5-fec9-59df-92d0-c58a36a8ae97'::uuid, '65a0fc6d-f5b2-52ba-ae86-b9df5e06dbe5'::uuid, '« Haber de + infinitif » appartient à un registre soutenu.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*He de irme* : obligation atténuée, plus littéraire que *tengo que*.', 7),
    ('fa997bff-1855-57fc-b3a0-20a473a4d392'::uuid, '65a0fc6d-f5b2-52ba-ae86-b9df5e06dbe5'::uuid, 'Comment exprimer un ordre direct ?', 'mcq', '["Par l’impératif : ¡Estudia!","Par le gérondif","Par l’infinitif seul","Par le futur"]'::jsonb, 0, 'Et à la forme négative, l’impératif emprunte au subjonctif : *¡No salgas!*', 8),
    ('20a8e59a-983c-5e2b-9413-37dac63d47ee'::uuid, '4f4899a2-496d-5fd5-9ff2-906b58aeb3e3'::uuid, 'Que signifie « Suelo levantarme temprano » ?', 'mcq', '["J’ai l’habitude de me lever tôt","Je me lève seul","Je viens de me lever","Je dois me lever tôt"]'::jsonb, 0, '*Soler* + infinitif exprime l’habitude à lui seul.', 1),
    ('e91f7005-d07a-5631-8241-3979b260e3f3'::uuid, '4f4899a2-496d-5fd5-9ff2-906b58aeb3e3'::uuid, 'À quels temps « soler » s’emploie-t-il ?', 'mcq', '["Au présent et à l’imparfait","À tous les temps","Au passé simple seulement","Au futur seulement"]'::jsonb, 0, 'L’habitude n’est pas un événement daté : ni passé simple, ni futur.', 2),
    ('4aedcd25-c58d-5d72-83ed-6246a017db41'::uuid, '4f4899a2-496d-5fd5-9ff2-906b58aeb3e3'::uuid, '« Soler » est un verbe à diphtongue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Suelo, sueles, suele… solemos, soléis, suelen.*', 3),
    ('711a758c-42bb-5f94-b9f4-3500408cbfaa'::uuid, '4f4899a2-496d-5fd5-9ff2-906b58aeb3e3'::uuid, 'Comment traduire « je l’ai rappelé » (une seconde fois) ?', 'mcq', '["Volví a llamarlo","Rellamé","Llamé otra vez lo","Vuelvo llamarlo"]'::jsonb, 0, '*Volver a* + infinitif remplace le préfixe « re- » du français.', 4),
    ('d4ef0c8a-2d94-5223-8694-70134e5992ca'::uuid, '4f4899a2-496d-5fd5-9ff2-906b58aeb3e3'::uuid, '« Acostumbrarse a » signifie « avoir l’habitude de ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La forme pronominale signifie « s’habituer à ».', 5),
    ('1aa89365-ed0f-5744-bac7-dc3594428331'::uuid, '4f4899a2-496d-5fd5-9ff2-906b58aeb3e3'::uuid, 'Quel temps exprime seul l’habitude passée ?', 'mcq', '["L’imparfait","Le passé simple","Le futur","Le conditionnel"]'::jsonb, 0, '*Cuando era pequeño, jugaba al fútbol.*', 6),
    ('95e120d7-51a3-5f5b-9f6c-3cb291ffcba4'::uuid, '4f4899a2-496d-5fd5-9ff2-906b58aeb3e3'::uuid, '« De vez en cuando » signifie…', 'mcq', '["De temps en temps","Toujours","Jamais","Chaque fois"]'::jsonb, 0, 'Entre *a menudo* (souvent) et *casi nunca* (presque jamais).', 7),
    ('877ffa41-891d-5875-856c-8fffe631e5e6'::uuid, '4f4899a2-496d-5fd5-9ff2-906b58aeb3e3'::uuid, '« Seguir + gérondif » exprime la continuation d’une action.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Sigo estudiando español* : je continue d’étudier l’espagnol.', 8),
    ('1afd2939-0356-5b78-a336-ed63c1694bd2'::uuid, '8058c2af-b6fc-5de9-8d9f-76545714ca81'::uuid, 'Que signifie « Serán las tres » ?', 'mcq', '["Il doit être trois heures","Il sera trois heures","Il était trois heures","Il faut qu’il soit trois heures"]'::jsonb, 0, 'Le futur de probabilité suppose sur le PRÉSENT.', 1),
    ('c467f3fd-2ea6-5619-b866-a5d82c577a0f'::uuid, '8058c2af-b6fc-5de9-8d9f-76545714ca81'::uuid, 'Le conditionnel de probabilité porte sur…', 'mcq', '["Le passé","Le présent","Le futur","L’avenir proche"]'::jsonb, 0, '*Serían las tres cuando llegó* : il devait être trois heures.', 2),
    ('ed46d47e-d55c-5d9b-b5d7-40e4372df05a'::uuid, '8058c2af-b6fc-5de9-8d9f-76545714ca81'::uuid, '« Puede que » est suivi du subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Puede que llueva* — sans exception.', 3),
    ('d62ff342-8310-5a97-8101-816e153ad900'::uuid, '8058c2af-b6fc-5de9-8d9f-76545714ca81'::uuid, 'Quel mode suit « a lo mejor » ?', 'mcq', '["L’indicatif","Le subjonctif","L’infinitif","Le gérondif"]'::jsonb, 0, 'C’est le piège : à la différence de *quizás*, *a lo mejor* garde l’indicatif.', 4),
    ('6472c1ed-7f89-567e-84c0-f2f6de617334'::uuid, '8058c2af-b6fc-5de9-8d9f-76545714ca81'::uuid, '« Debe estudiar » et « Debe de estudiar » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier exprime l’obligation, le second la supposition.', 5),
    ('3ca7a8a6-5675-514d-b8b1-767ea099d23f'::uuid, '8058c2af-b6fc-5de9-8d9f-76545714ca81'::uuid, '« Quizás venga » plutôt que « quizás viene » signale…', 'mcq', '["Une probabilité plus faible","Une certitude","Un ordre","Un futur proche"]'::jsonb, 0, 'Le subjonctif marque la réserve, l’indicatif l’assurance.', 6),
    ('7d9e7e5c-4bf2-5d74-8d74-964d85a9dcbb'::uuid, '8058c2af-b6fc-5de9-8d9f-76545714ca81'::uuid, '« Habrá salido » suppose sur un fait accompli.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le futur antérieur de probabilité : il a dû sortir.', 7),
    ('29aaa6d3-92fd-5cd1-ab3e-c100fe6c4c93'::uuid, '8058c2af-b6fc-5de9-8d9f-76545714ca81'::uuid, 'Comment traduire « il devait avoir vingt ans » ?', 'mcq', '["Tendría veinte años","Tendrá veinte años","Tuvo veinte años","Tenía que tener veinte años"]'::jsonb, 0, 'Conditionnel de probabilité, pour supposer sur le passé.', 8),
    ('fbe8a4b9-9502-5953-a0d5-0647c9d3cc0f'::uuid, '36021877-e1d7-5f41-bfa5-1298e78c72a1'::uuid, 'Comment forme-t-on l’impératif négatif ?', 'mcq', '["Avec le subjonctif présent","Avec l’impératif affirmatif précédé de no","Avec l’infinitif","Avec le futur"]'::jsonb, 0, '*No hables*, *no comas*, *no salgáis*.', 1),
    ('eeb87ef3-d3f8-5181-bf81-9a8cdfd411ff'::uuid, '36021877-e1d7-5f41-bfa5-1298e78c72a1'::uuid, 'Quel est l’impératif de « hacer » à la deuxième personne du singulier ?', 'mcq', '["Haz","Hace","Haga","Haced"]'::jsonb, 0, 'Comme *di*, *ve*, *pon*, *sal*, *sé*, *ten*, *ven*.', 2),
    ('7045230d-7078-5b77-bfa8-a03c12d0c793'::uuid, '36021877-e1d7-5f41-bfa5-1298e78c72a1'::uuid, 'Après « Te aconsejo que », le verbe est au subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Te aconsejo que vayas al médico.*', 3),
    ('76e35eb2-2bbf-5d2c-b0a7-af2a45032e6a'::uuid, '36021877-e1d7-5f41-bfa5-1298e78c72a1'::uuid, 'Comment traduire « tu devrais te reposer » ?', 'mcq', '["Deberías descansar","Debes descansar","Debías descansar","Debe de descansar"]'::jsonb, 0, 'Le conditionnel atténue l’obligation en conseil.', 4),
    ('0f91ffbd-8df6-56c1-99a0-49ec65c47b78'::uuid, '36021877-e1d7-5f41-bfa5-1298e78c72a1'::uuid, '« Ojalá pudiera ayudarte » exprime un souhait réalisable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’imparfait du subjonctif marque au contraire l’improbable.', 5),
    ('13201ed2-48fb-5fc7-80ee-63e19bde0d37'::uuid, '36021877-e1d7-5f41-bfa5-1298e78c72a1'::uuid, 'Que signifie « Yo que tú, iría al médico » ?', 'mcq', '["À ta place, j’irais chez le médecin","Moi et toi allons chez le médecin","Je te vois chez le médecin","Je dois aller chez le médecin"]'::jsonb, 0, 'La tournure se poursuit au conditionnel.', 6),
    ('097761cb-5cf2-5a6a-989d-745e844080a6'::uuid, '36021877-e1d7-5f41-bfa5-1298e78c72a1'::uuid, 'L’impératif affirmatif soude les pronoms au verbe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Dímelo* ; au négatif, ils repassent devant : *no me lo digas*.', 7),
    ('6c125749-bb6e-5c85-9059-5b55849f5ad0'::uuid, '36021877-e1d7-5f41-bfa5-1298e78c72a1'::uuid, 'Quel mode suit « ¿Y si… ? » pour suggérer ?', 'mcq', '["L’indicatif","Le subjonctif","L’impératif","Le conditionnel"]'::jsonb, 0, '*¿Y si salimos esta noche?*', 8),
    ('4339300e-7b8f-580b-8465-7c2ab0e195b5'::uuid, '4478d5bf-f91d-556c-829f-6e1e409125db'::uuid, 'Quelle est la première personne du présent de « hacer » ?', 'mcq', '["Hago","Haco","Hazo","Hacio"]'::jsonb, 0, 'Verbe à *yo* irrégulier : le reste de la conjugaison est régulier.', 1),
    ('9b9d0add-634d-55f6-ac36-b7ddc8d428c9'::uuid, '4478d5bf-f91d-556c-829f-6e1e409125db'::uuid, 'Quelle est la première personne du présent de « conocer » ?', 'mcq', '["Conozco","Conoco","Conosco","Conogo"]'::jsonb, 0, 'Comme tous les verbes en -cer et -cir : *parezco*, *conduzco*.', 2),
    ('88e9ecb7-d7a3-5112-ae84-2e600c3922f8'::uuid, '4478d5bf-f91d-556c-829f-6e1e409125db'::uuid, '« Ser », « ir », « haber » et « estar » sont totalement irréguliers.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Soy*, *voy*, *he*, *estoy* : aucune ne suit un modèle.', 3),
    ('7bc276b4-2170-5f19-a9bd-b541fa85eecb'::uuid, '4478d5bf-f91d-556c-829f-6e1e409125db'::uuid, 'Que signifie « Estudio español desde hace dos años » ?', 'mcq', '["J’étudie l’espagnol depuis deux ans","J’ai étudié l’espagnol il y a deux ans","J’étudierai deux ans","J’étudiais depuis deux ans"]'::jsonb, 0, 'Le présent couvre l’action commencée dans le passé et qui dure.', 4),
    ('e2f01e97-d4a3-5b8f-9ffb-8a61ea685bc9'::uuid, '4478d5bf-f91d-556c-829f-6e1e409125db'::uuid, '« Tener » cumule un yo irrégulier et une diphtongue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Tengo*, puis *tienes, tiene… tenemos, tenéis, tienen*.', 5),
    ('2bd4bd69-3938-57ae-b468-03dad3eab76b'::uuid, '4478d5bf-f91d-556c-829f-6e1e409125db'::uuid, 'Pourquoi « estás » porte-t-il un accent écrit ?', 'mcq', '["L’accent tonique tombe sur la terminaison","C’est un pluriel","Pour le distinguer de « estas »","C’est un subjonctif"]'::jsonb, 0, 'Le second motif est vrai aussi, mais la raison première est prosodique.', 6),
    ('bbcbd5d9-51bc-5171-bee7-c98db901015f'::uuid, '4478d5bf-f91d-556c-829f-6e1e409125db'::uuid, 'Les verbes en -er et en -ir se conjuguent identiquement au présent, sauf…', 'mcq', '["À nosotros et vosotros","À yo et tú","À él et ellos","Nulle part"]'::jsonb, 0, '*Comemos / vivimos*, *coméis / vivís*.', 7),
    ('8695d2a4-8972-5c28-b0cb-ec5e0ae51f95'::uuid, '4478d5bf-f91d-556c-829f-6e1e409125db'::uuid, 'Le présent peut exprimer un futur proche.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Mañana salgo a las ocho.*', 8),
    ('826de13a-77c7-5608-999a-87fdb6e0337e'::uuid, 'a9156d42-2076-5c16-af78-0164bb4faf4d'::uuid, 'De quelle forme part-on pour construire le subjonctif présent ?', 'mcq', '["De la première personne du présent de l’indicatif","De l’infinitif","Du participe passé","Du passé simple"]'::jsonb, 0, 'On retire le -o et on inverse la voyelle des terminaisons.', 1),
    ('2d22e2d5-2160-50dd-80dd-3b4e074f7748'::uuid, 'a9156d42-2076-5c16-af78-0164bb4faf4d'::uuid, 'Quelle voyelle prennent les terminaisons du subjonctif des verbes en -ar ?', 'mcq', '["E (hable, hables…)","A","I","O"]'::jsonb, 0, 'Et inversement, les -er et -ir prennent un a : *coma, comas*.', 2),
    ('2737b5c6-1517-551c-90a2-c25bb41aa6ce'::uuid, 'a9156d42-2076-5c16-af78-0164bb4faf4d'::uuid, 'Quel est le subjonctif présent de « tener » à la première personne ?', 'mcq', '["Tenga","Tena","Tienga","Tuviera"]'::jsonb, 0, 'Il hérite du *yo* irrégulier : *tengo → tenga*.', 3),
    ('4bae94f3-dbb5-5c1e-b4a9-00b610fd168c'::uuid, 'a9156d42-2076-5c16-af78-0164bb4faf4d'::uuid, 'Après « Cuando » suivi d’une valeur de futur, on emploie…', 'mcq', '["Le subjonctif","Le futur","L’indicatif présent","Le conditionnel"]'::jsonb, 0, '*Cuando llegues, llámame* — piège majeur du francophone.', 4),
    ('64de641f-ee91-5c6c-9791-426b5d8d5359'::uuid, 'a9156d42-2076-5c16-af78-0164bb4faf4d'::uuid, '« Ser », « ir », « haber », « saber », « dar » et « estar » ont un subjonctif irrégulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Sea*, *vaya*, *haya*, *sepa*, *dé*, *esté*.', 5),
    ('1590b55d-cb8d-562a-acca-51b5ee016828'::uuid, 'a9156d42-2076-5c16-af78-0164bb4faf4d'::uuid, 'Au subjonctif, l’affaiblissement touche « nosotros » et « vosotros ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Pidamos*, *pidáis* — contrairement à la diphtongue.', 6),
    ('8618327e-bdaa-546f-b9e0-1f47a744dc4b'::uuid, 'a9156d42-2076-5c16-af78-0164bb4faf4d'::uuid, 'Quelle conjonction est toujours suivie du subjonctif ?', 'mcq', '["Para que","Porque","Aunque toujours","Ya que"]'::jsonb, 0, 'Comme *antes de que*, *sin que*, *a menos que*.', 7),
    ('654b2f43-bc05-5a19-923c-9c7a4719999a'::uuid, 'a9156d42-2076-5c16-af78-0164bb4faf4d'::uuid, 'Quel est le subjonctif présent de « ir » ?', 'mcq', '["Vaya","Vaiga","Iría","Fuera"]'::jsonb, 0, 'L’un des six irréguliers dont la 1re personne ne finit pas par -o.', 8),
    ('1f892bb3-41d9-5d46-a990-f759852a26bc'::uuid, 'f628f408-3a23-5f22-a6bf-905480c2ea65'::uuid, 'Combien de verbes sont irréguliers à l’imparfait ?', 'mcq', '["Trois : ser, ir, ver","Aucun","Six","Dix"]'::jsonb, 0, '*Era*, *iba*, *veía* — la seule liste courte de la conjugaison espagnole.', 1),
    ('14e7e06d-e593-53c8-b5ce-d4e11ea578cb'::uuid, 'f628f408-3a23-5f22-a6bf-905480c2ea65'::uuid, 'Quelle est la terminaison de l’imparfait des verbes en -ar ?', 'mcq', '["-aba","-ía","-ió","-aría"]'::jsonb, 0, 'Les -er et -ir font *-ía*.', 2),
    ('24cd920e-06f5-5702-a8fc-52a2aedbc0f2'::uuid, 'f628f408-3a23-5f22-a6bf-905480c2ea65'::uuid, '« Cuando era pequeño, jugaba al fútbol » exprime une habitude.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’emploi principal de l’imparfait avec la description.', 3),
    ('c7cabc27-04ef-513f-bae5-43df3b81cb32'::uuid, 'f628f408-3a23-5f22-a6bf-905480c2ea65'::uuid, 'Dans « Llovía cuando salí », quel temps fait avancer l’action ?', 'mcq', '["Salí (passé simple)","Llovía (imparfait)","Les deux","Aucun"]'::jsonb, 0, 'L’imparfait pose le décor, le passé simple marque l’événement.', 4),
    ('2a19a58e-1d46-5833-b03b-2f49722617fb'::uuid, 'f628f408-3a23-5f22-a6bf-905480c2ea65'::uuid, 'Quel est l’imparfait de « ver » ?', 'mcq', '["Veía","Vía","Veaba","Vía/vea"]'::jsonb, 0, 'Il se forme sur l’ancien infinitif *veer*.', 5),
    ('f314c68a-a6f9-52ff-acd6-21d8793ec502'::uuid, 'f628f408-3a23-5f22-a6bf-905480c2ea65'::uuid, '« Ayer llovió » et « Ayer llovía » disent exactement la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier rapporte un fait, le second décrit un contexte.', 6),
    ('159b8dd5-e3d2-5dfe-bd3e-be026d5cafe6'::uuid, 'f628f408-3a23-5f22-a6bf-905480c2ea65'::uuid, 'Que signifie « Quería pedirle un favor » dans une demande polie ?', 'mcq', '["Je voudrais vous demander un service","Je voulais et je ne veux plus","J’ai demandé un service","Je devrai demander un service"]'::jsonb, 0, 'L’imparfait de politesse atténue la demande.', 7),
    ('c326ac31-0b5a-5873-ae2a-a3c05b945f4b'::uuid, 'f628f408-3a23-5f22-a6bf-905480c2ea65'::uuid, 'L’imparfait peut exprimer une action en cours interrompue par une autre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Mientras cenábamos, sonó el teléfono.*', 8),
    ('db744dac-c6f8-5e4b-8cda-ed0cb939b247'::uuid, 'f6956b0f-a1dd-579c-92ee-7e922d9008f6'::uuid, 'Comment se forme le pretérito perfecto ?', 'mcq', '["Haber au présent + participe passé","Tener + participe passé","Ser + participe passé","Estar + gérondif"]'::jsonb, 0, '*He comido*, *has estudiado*.', 1),
    ('6799488f-0015-5077-af93-190ca8fd55b2'::uuid, 'f6956b0f-a1dd-579c-92ee-7e922d9008f6'::uuid, 'Quel marqueur appelle le pretérito perfecto ?', 'mcq', '["Hoy","Ayer","El año pasado","En 1990"]'::jsonb, 0, 'Comme *esta semana*, *este año*, *ya*, *todavía no*.', 2),
    ('2028767f-a86c-5b87-a756-9078e55b1494'::uuid, 'f6956b0f-a1dd-579c-92ee-7e922d9008f6'::uuid, 'Le participe passé s’accorde avec le sujet au pretérito perfecto.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avec *haber*, jamais d’accord : *ellas han llegado*.', 3),
    ('e7075eb4-e137-5b38-8a38-5a4e2f8c4654'::uuid, 'f6956b0f-a1dd-579c-92ee-7e922d9008f6'::uuid, '« Este año he viajado mucho » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La période n’est pas achevée : le passé composé s’impose.', 4),
    ('3c8dd186-1835-540b-959f-cc5b3569635c'::uuid, 'f6956b0f-a1dd-579c-92ee-7e922d9008f6'::uuid, 'Quelle est la différence entre « Hoy he ido al cine » et « Ayer fui al cine » ?', 'mcq', '["Le premier appartient à une période non achevée","Aucune","Le premier est plus soutenu","Le second est un plus-que-parfait"]'::jsonb, 0, 'Le passé simple coupe du présent, le passé composé raccroche.', 5),
    ('87dfef32-fca3-55c8-9658-a58b8cfbb747'::uuid, 'f6956b0f-a1dd-579c-92ee-7e922d9008f6'::uuid, 'En Amérique latine, le passé simple absorbe souvent le passé composé.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Hoy comí paella* y est courant, sans être une faute.', 6),
    ('17f1b1b1-392b-541d-9168-d030c3d10df2'::uuid, 'f6956b0f-a1dd-579c-92ee-7e922d9008f6'::uuid, 'Que peut-on intercaler entre « haber » et le participe ?', 'mcq', '["Rien","Un adverbe","Une négation","Un pronom"]'::jsonb, 0, 'Le bloc est soudé : *No lo he visto nunca*.', 7),
    ('cf8a6f87-ed56-5708-9de7-73d0c436090f'::uuid, 'f6956b0f-a1dd-579c-92ee-7e922d9008f6'::uuid, '« Nunca he estado en México » est un bilan de vie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La période de référence est la vie entière, non achevée.', 8),
    ('5983d4fd-7021-5c7e-9567-75cd14d15a52'::uuid, '90b4dd90-eb0f-5e24-bdd5-34565de64105'::uuid, 'Quelles terminaisons prend le passé simple des verbes en -ar ?', 'mcq', '["-é, -aste, -ó, -amos, -asteis, -aron","-í, -iste, -ió…","-aba, -abas…","-aré, -arás…"]'::jsonb, 0, '*Hablé, hablaste, habló, hablamos, hablasteis, hablaron.*', 1),
    ('c4208586-a859-5059-a953-2f779c0795e6'::uuid, '90b4dd90-eb0f-5e24-bdd5-34565de64105'::uuid, '« Hablo » et « habló » se distinguent uniquement par l’accent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’un est un présent, l’autre un passé simple : l’accent est distinctif.', 2),
    ('9bafc0c6-defb-5938-93d0-26d507eadb6d'::uuid, '90b4dd90-eb0f-5e24-bdd5-34565de64105'::uuid, 'Quel est le passé simple de « tener » à la première personne ?', 'mcq', '["Tuve","Tení","Tuvé","Tenió"]'::jsonb, 0, 'Prétérit fort : radical *tuv-* et terminaisons sans accent.', 3),
    ('0c27ea12-a746-54ba-b16b-e6f916e8afe9'::uuid, '90b4dd90-eb0f-5e24-bdd5-34565de64105'::uuid, 'Quelle est la troisième personne du pluriel de « decir » au passé simple ?', 'mcq', '["Dijeron","Dijieron","Decieron","Digieron"]'::jsonb, 0, 'Après un radical en -j, le i de la terminaison disparaît.', 4),
    ('6ce0f3bf-ae46-56a4-9b0f-f37c203648de'::uuid, '90b4dd90-eb0f-5e24-bdd5-34565de64105'::uuid, '« Ser » et « ir » ont la même forme au passé simple.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Fui, fuiste, fue…* : seul le contexte permet de trancher.', 5),
    ('8de9bd9d-5c75-5a9d-a327-57d34ab474de'::uuid, '90b4dd90-eb0f-5e24-bdd5-34565de64105'::uuid, 'Quel marqueur appelle le passé simple ?', 'mcq', '["Ayer","Hoy","Esta semana","Todavía no"]'::jsonb, 0, 'Comme *anoche*, *el año pasado*, *en 1975*.', 6),
    ('d5be4d75-e740-5994-a1d2-3fa4429df79c'::uuid, '90b4dd90-eb0f-5e24-bdd5-34565de64105'::uuid, 'Quelle est la troisième personne de « dormir » au passé simple ?', 'mcq', '["Durmió","Dormió","Duermió","Durmó"]'::jsonb, 0, 'Les verbes en -ir portent l’affaiblissement aux deux 3es personnes.', 7),
    ('f2272018-d35f-517c-9e0e-39ca0bfdacc7'::uuid, '90b4dd90-eb0f-5e24-bdd5-34565de64105'::uuid, 'Dans un récit, le passé simple fait avancer l’action.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’imparfait, lui, décrit le cadre : *Era de noche… De repente, sonó el timbre.*', 8),
    ('0a33fd88-20cc-5ec1-a436-6307a98e8524'::uuid, 'b16587ba-2e36-5217-8594-e907c12f4053'::uuid, 'Sur quoi se construit le futur simple espagnol ?', 'mcq', '["Sur l’infinitif entier","Sur le radical du présent","Sur le participe passé","Sur le passé simple"]'::jsonb, 0, '*Hablaré*, *comeré*, *viviré* : mêmes terminaisons pour les trois groupes.', 1),
    ('d8e9a57f-3acb-5e9d-95c2-e41859ccec03'::uuid, 'b16587ba-2e36-5217-8594-e907c12f4053'::uuid, 'Quel est le futur de « tener » à la première personne ?', 'mcq', '["Tendré","Teneré","Tenré","Tendría"]'::jsonb, 0, 'Un d remplace la voyelle, comme dans *pondré*, *vendré*, *saldré*.', 2),
    ('521ccd27-076d-5839-a62c-ab046e300f36'::uuid, 'b16587ba-2e36-5217-8594-e907c12f4053'::uuid, 'Le conditionnel se forme sur le même radical que le futur.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec les terminaisons de l’imparfait en -ía : *tendría*, *haría*, *diría*.', 3),
    ('188d8631-5b7f-521c-acff-0377d2e3d817'::uuid, 'b16587ba-2e36-5217-8594-e907c12f4053'::uuid, 'Que met-on après « cuando » avec une valeur de futur ?', 'mcq', '["Le subjonctif présent","Le futur simple","L’indicatif présent","Le conditionnel"]'::jsonb, 0, '*Cuando llegues, llámame* — jamais « cuando llegarás ».', 4),
    ('704cac8e-89b6-557a-ab2b-ed9b38388952'::uuid, 'b16587ba-2e36-5217-8594-e907c12f4053'::uuid, 'Quel est le futur de « hacer » ?', 'mcq', '["Haré","Haceré","Hará","Hicé"]'::jsonb, 0, 'Radical raccourci, comme *decir → diré*.', 5),
    ('bc77661b-3960-5819-9632-9633410a317e'::uuid, 'b16587ba-2e36-5217-8594-e907c12f4053'::uuid, '« Serán las tres » exprime une probabilité sur le présent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le futur de supposition : il doit être trois heures.', 6),
    ('5d133d1d-8a05-5c03-80b9-86edd6ce45fb'::uuid, 'b16587ba-2e36-5217-8594-e907c12f4053'::uuid, 'Quelle forme du futur ne porte pas d’accent écrit ?', 'mcq', '["Nosotros (hablaremos)","Yo","Tú","Ellos"]'::jsonb, 0, 'Toutes les autres en portent un : *hablaré, hablarás, hablará, hablaréis, hablarán*.', 7),
    ('0cc129b1-d284-5bc0-b71a-fdae9308102d'::uuid, 'b16587ba-2e36-5217-8594-e907c12f4053'::uuid, '« Ir a + infinitif » exprime l’intention ou l’imminence.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Voy a estudiar* : le futur proche, très employé à l’oral.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('espagnol');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('espagnol')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 231 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 231 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
